window.__LEX={"G5600":"<h1>o</h1>\n<p>Strong n° 5600 <i>Prononciation [o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être, peut être, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὦ, ᾖς, ᾖ</b>, <i>sbj. prés. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ω - ὦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n65 fois dans 61 versets de 18 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (15)</li>\n<li>Actes (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (11)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (2)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Philémon (1)</li>\n<li>Jacques (3)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5601":"<h1>Obed</h1>\n<p>Strong n° 5601 <i>Prononciation [o-bade']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Obed (ou Jobed) = « qui sert (Dieu) »\n<ol><li>le grand-père du roi David</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ωβηδ</font> &lt; עובד - <font face=\"Georgia\">Ἰωβήδ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT).\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5602":"<h1>hode</h1>\n<p>Strong n° 5602 <i>Prononciation [ho'-deh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ici, en cet endroit, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὧδε</b>, <i>adv. :</i><br><b>   I</b> <i>adv. de manière,</i> ainsi :<br><b>      1</b> de cette manière, <i>se rapporte à ce qui précède ou à ce qui suit :</i> εἴπερ ὧδ' ἔχει, SOPH. <i>Ph. 116,</i> s’il en est ainsi ; ὧδ' ἠμείψατο, SOPH. <i>Ph. 378,</i> il répondit ainsi, <i>etc. ; en relat. avec</i> ὡς : ὧδε… ὡς ὅδε οἶνος, IL. <i>3, 300,</i> ainsi… que ce vin ; <i>cf</i>. OD. <i>19, 312 ; avec</i> ὥσπερ, SOPH. <i>O.R. 276 ; avec</i> ὅπως, SOPH. <i>El. 1301 ; joint à d’autres adv. ou particules :</i> ὧδ' αὔτως, IL. <i>15, 513,</i> ainsi justement ; ὧδέ πως, XÉN. <i>Cyr. 1, 6, 12 ; Mem. 2, 1, 21 ;</i> PLAT. <i>Rsp. 393</i> d ; LUC. <i>Herm. 32, etc</i>. à peu près ainsi ; <i>avec un inf. :</i> ὧδε εἰπεῖν, ATT. pour ainsi parler ; <i>avec un gén. :</i> ὧδε γένους ἥκεις, EUR. <i>Her. 214,</i> tu viens ainsi de la même race ; <i>cf</i>. EUR. <i>Ph. 372 ;</i><br><b>      2</b> dans l’état où l’on est : πρόμολ' ὧδε, IL. <i>18, 392,</i> viens ici ; ὧδε θέεις, IL. <i>17, 75,</i> tu cours maintenant comme tu cours, <i>càd</i>. sans résultat ;<br><b>      3</b> tellement, à ce point : ὧδε τλήμων, SOPH. <i>El. 275,</i> à ce point malheureuse ; <i>suivi de</i> ὥστε, <i>cf</i>. EUR. <i>El. 265, ou d’une prop. relat</i>. ESCHL. <i>Pr. 159 ; avec</i> εἰ, SOPH. <i>O.C. 272 ;</i> PLAT. <i>Crat. 391</i> a ; <i>renforcé par</i> μάλα, OD. <i>21, 196 ; par</i> ἄγαν, SOPH. <i>El. 884 ; par</i> τόσον, OD. <i>9, 403,</i> à ce point que, <i>etc. ;</i><br><b>   II</b> <i>adv. de lieu,</i> ici, <i>sans mouv. correspond. à</i> τηνεί, THCR. <i>Idyl. 1, 106 ; cf. 107, 120, 121, etc. ; joint à</i> ἐκεῖ : ὧδε κἀκεῖ, PLUT. <i>M. 34</i> a, <i>etc</i>. ici et là ; <i>avec mouv</i>. SOPH. <i>O.R. 7 ; O.C. 1251, 1286 ; joint à</i> ἐκεῖσε : <i>avec mouv</i>. ὧδε κἀκεῖσε, LUC. <i>Herm. 1,</i> ici et là ; <i>cf</i>. SPT. <i>Gen. 19, 12 ; Ex. 3, 5, etc. ;</i> NT. <i>Matth. 17, 7, etc</i>.<br><span><b>Étym</b>. <i>adv. de</i> ὅδε.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωδε - ὧδε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n60 fois dans 56 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (9)</li>\n<li>Luc (14)</li>\n<li>Jean (5)</li>\n<li>Actes (2)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G5603":"<h1>ode</h1>\n<p>Strong n° 5603 <i>Prononciation [o-day']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un chant, une ode, un cantique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ᾠδή, ῆς (ἡ) :<br>   I</b> chant :<br><b>      1</b> <i>en gén</i>. HH. <i>Ap. 20, Cer. 494, etc. ; p. opp. à</i> λέξις, PLAT. <i>Leg. 816</i> d ; <i>joint à</i> μύθοις καὶ λόγοις, PLAT. <i>Leg. 664</i> a ; <i>particul</i>. chant de deuil, SOPH. <i>El. 88, Aj. 630 ;</i> PLAT. <i>Leg. 800</i> e, <i>etc. ;</i> chant de louange, hymne, EUR. <i>El. 865, Suppl. 1225, etc. ;</i> PLAT. <i>Leg. 947, etc. ; particul</i>. chant d’hymen, AR. <i>Av. 1729, etc. ;</i> chant religieux, PLAT. <i>Leg. 799</i> a ; chant de guerre, XÉN. <i>An. 4, 3, 27, etc. ;</i> chant avec accompagnement d’instruments, PLAT. <i>Leg. 722</i> d ; <i>p. suite,</i> poésie lyrique, PLAT. <i>Phædr. 245</i> a ; <i>joint à</i> μέλη, PLAT. <i>Rsp. 398</i> c, <i>399</i> c, <i>etc. ;</i><br><b>      2</b> chant magique, LGS <i>2, 7 ;</i><br><b>   II</b> action de chanter, PLUT. <i>Crass. 3, etc. ;</i> LUC. <i>Tim. 55, etc. ; en parl. d’oiseaux,</i> ARSTT. <i>H.A. 9, 8, 4 ; particul</i>. chant du coq, HLD. <i>7 ;</i> LGS <i>3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ᾠδά <span>[ᾱ]</span> EUR. <i>Tr. 514</i>.<br><span><b>Étym</b>. <i>contr. p</i>. ἀοιδή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωδη - ᾠδή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> est le terme générique ;  et  sont spécifiques,\n<br><br> désignant un chant qui a pris son caractère général dans les Psaumes de l'AT, bien que non limité à eux,  est un hymne, un chant de louange. Tandis que l'idée maîtresse de  est d'être un accompagnement musical, et que  est une louange à Dieu,  est le mot global pour un chant, accompagné ou non, pour une louange ou tout autre sujet. Il est donc tout à fait possible que le même chant soit décrit par ces trois différents mots.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G5604":"<h1>odin</h1>\n<p>Strong n° 5604 <i>Prononciation [o-deen']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la souffrance de l'enfantement, la peine d'un accouchement, l'angoisse d'une naissance</li>\n<li>l'angoisse intolérable, dans la pensée des calamités qui précéderont la venue du Messie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠδίν, ῖνος (ἡ)</b> <span>[ῑ]</span> <i>forme postér. p</i>. ὠδίς, SPT. <i>Esaï. 37, 5 ;</i> NT. <i>1Thess. 5, 3</i>.<br><br>\n<b>ὠδίς, ῖνος (ἡ)</b> <span>[ῑ]</span><br><b>   I</b> douleur de l’enfantement, <i>d’où</i> enfantement :<br><b>      1</b> <i>au propre,</i> PD. <i>O. 6, 74 ; N. 1, 55 ;</i> SOPH. <i>O.C. 533, fr. 670 ; d’ord. au plur</i>. IL. <i>11, 271 ;</i> HH. <i>Ap. 92 ;</i> PD. <i>P. 9, 149 ;</i> EUR. <i>Suppl. 920, Bacch. 89, Ion 452, 7 ; Ph. 355, etc. ;</i> PLUT. <i>M. 238</i> e ; <i>en parl. d’animaux,</i> EL. <i>V.H. 10, 3, etc. ; N.A. 5, 34, etc. ;</i> ANTH. <i>7, 383 ;</i><br><b>      2</b> <i>p. ext</i>. toute douleur violente, souffrance cruelle (physique <i>ou</i> morale) ESCHL. <i>Ch. 211, Suppl. 770 ; au plur</i>. SOPH. <i>Tr. 42 ;</i> PLAT. <i>Rsp. 493</i> b, <i>Phædr. 251</i> e ; <i>joint à</i> ὀδύναις, PLAT. <i>Rsp. 574</i> a ; <i>à</i> τρόμους, PLUT. <i>Sol. 7 ; p. opp. à</i> ἡδονάς, PLAT. <i>Tim. 86</i> c, <i>etc. ;</i><br><b>   II</b> fruit de l’enfantement, enfant, rejeton, PD. <i>O. 6, 51 ;</i> ESCHL. <i>Ag. 1417 ;</i> EUR. <i>Ion 45, etc. ;</i> ANTH. <i>7, 549 ; en parl. d’animaux,</i> EUR. <i>H.f. 1040 ; en parl. d’œufs,</i> NIC. <i>Al. 165 ; p. anal</i>. ὠδ. θαλάσσης, ANTH. <i>9, 386,</i> enfant de la mer, <i>en parl. d’Aphrodite ; p. ext</i>. toute production laborieuse : ὠδ. μελίσσης, NONN. le miel, laborieux produit de l’abeille ; <i>en parl. des travaux de l’esprit,</i> HIM. <i>18, 3 ;</i> TRIPHIOD. <i>117, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl</i>. ὠδῖσι, ESCHL. <i>Ch. 209 ;</i> PLAT. <i>Ep. 313</i> a ; <i>poét</i>. ὠδίνεσσιν, THCR. <i>Idyl. 17, 61</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωδιν - ὠδίν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5605":"<h1>odino</h1>\n<p>Strong n° 5605 <i>Prononciation [o-dee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ressentir la souffrance de la naissance d'un enfant, accoucher</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠδίνω</b> <span>(<i>impf</i>. ὤδινον, <i>f</i>. ὠδινῶ <i>et</i> ὠδινήσω, <i>ao</i>. ὠδίνησα <i>et</i> ὤδινα ; <i>pass. seul. ao</i>. ὠδινήθην)</span><br><b>A <i>intr. :</i><br>   I</b> éprouver les douleurs de l’enfantement, enfanter avec douleur, <i>abs</i>. IL. <i>11, 269 ;</i> AR. <i>Th. 502, etc. ;</i> PLAT. <i>Rsp. 395</i> e ; PLUT. <i>Thes. 20 ;</i> SPT. <i>Esaï. 23, 4 ; 26, 17 ; 48, 10 ;</i> NT. <i>Apoc. 12, 2 ; avec l’acc</i>. EUR. <i>I.A. 1234, etc. ;</i> SPT. <i>Esaï. 51, 2 ; en parl. d’animaux,</i> EL. <i>N.A. 2, 46 ; p. anal</i>. enfanter avec effort, produire, <i>en parl. des abeilles,</i> CHRISTOD. <i>Ecphr. 343 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> éprouver une douleur violente : ὠδίνων ὀδύνῃσιν, OD. <i>9, 415,</i> souffrant des douleurs cruelles ; <i>au mor</i>. être dans l’angoisse, être anxieux, SOPH. <i>Aj. 794 ;</i> EUR. <i>Her. 644 ;</i> PLUT. <i>M. 1090</i> d ; <i>avec un acc</i>. συμφορᾶς βάρος, SOPH. <i>Tr. 325,</i> garder renfermé dans son sein le douloureux fardeau de son infortune ; περί τινος, PLAT. <i>Theæt. 210</i> b ; ὑπέρ τινος, EUR. <i>Hipp. 258,</i> souffrir pour qqn ;<br><b>      2</b> porter dans son sein, nourrir dans son esprit : τι, PLAT. <i>Theæt. 148</i> e, <i>151</i> b, qqe ch. ; <i>avec un inf</i>. méditer de, HLD. <i>2, 21 ;</i> εἴς τι, HLD. <i>5, 32,</i> avoir un ardent désir de qqe ch. ;<br><b>B <i>tr.</i></b> faire trembler (<i>litt</i>. comme une femme dans les douleurs de l’enfantement) <i>acc</i>. SPT. <i>Sir. 43, 16 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ὠδινησάμην)</span> <i>m. sign</i>. AQU. <i>Ps. 113, 7</i>.<br><span><b>Étym</b>. ὠδίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωδινω - ὠδίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Galates (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5606":"<h1>omos</h1>\n<p>Strong n° 5606 <i>Prononciation [o'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une épaule</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὠμός, ή, όν :<br>   I</b> cru, <i>càd. :</i><br><b>      1</b> non cuit : <i>p. opp. à</i> ὀπταλέος, OD. <i>12, 396 ; à</i> ὀπτός, SPT. <i>Ex. 12, 9 ;</i> ὠμὰ κρέα, IL. <i>22, 347,</i> viandes crues ; κριθαὶ ὠμαί, LUC. <i>V. auct. 10,</i> orge non grillée ; ὕδωρ ὠμόν, ALEX. (<i>Com. fr. 3, 474</i>) eau non bouillie ; ὠμὸν βιϐρώσκειν τινά, IL. <i>4, 35 ;</i> καταφαγεῖν τινα, XÉN. <i>An. 4, 8, 14,</i> ἐσθίειν τινα, XÉN. <i>Hell. 3, 3, 6 ;</i> PHILSTR. <i>V. Ap. 4, 36, l. 30 ; etc. ;</i> manger <i>ou</i> dévorer qqn vivant ; <i>en parl. des animaux,</i> cheval, XÉN. <i>Eq. 1, 7, etc. ;</i> chien, XÉN. <i>Cyn. 4, 1 ; adv. :</i> ὠμά τι δάσασθαι, IL. <i>23, 21,</i> manger qqn cru ; <i>p. suite,</i> indigeste, PLUT. <i>M. 33</i> d, <i>131</i> c ; <i>d’où en gén</i>. fade, insipide, GEOP. <i>2, 6, 2 ;</i><br><b>      2</b> non mûr, <i>en parl. d’un fruit,</i> XÉN. <i>Œc. 10, 19 ;</i> PHÆNIAS (ATH. <i>68</i> d) ; <i>p. opp. à</i> πέπων, AR. <i>Eq. 260 ; fig</i>. non parvenu à son développement, qui n’est pas à point, prématuré, précoce ; ὠμὸν γῆρας, OD. <i>15, 357 ;</i> HÉS. <i>Sc. 707,</i> vieillesse prématurée (mais vieillesse morose, PLUT. <i>Mar. 2</i>) ; ὠμὸς τόκος, PHILSTR. <i>p. 555,</i> enfant qui naît avant terme ;<br><b>      3</b> non amolli (par le soleil), <i>d’où</i> non en état d’être travaillé, <i>en parl. de la terre,</i> XÉN. <i>Œc. 16, 15 ;</i><br><b>      4</b> non desséché (blé, <i>etc</i>.) LUC. <i>As. 17, etc. ;</i><br><b>   II</b> <i>au mor. :</i><br><b>      1</b> non civilisé, grossier, <i>joint à</i> ἀπαίδευτος, PLAT. <i>Ax. 369</i> a ;<br><b>      2</b> dur, cruel, inhumain, <i>en parl. de pers</i>. SOPH. <i>Ant. 471, O.R. 828 ;</i> EUR. <i>Hec. 359 ;</i> SPT. <i>2Macc. 7, 27, etc. ; joint à</i> χαλεπός, XÉN. <i>An. 2, 6, 12 ; p. opp. à</i> φιλόφρων, XÉN. <i>Mem. 3, 1, 6 ; en parl. de choses</i> (âme, loi, <i>etc</i>.) ESCHL. <i>Sept. 518, Suppl. 184 ;</i> THC. <i>3, 36, 81 ;</i> SOPH. <i>Aj. 548 ;</i> PLAT. <i>Leg. 718</i> d, <i>etc. ;</i> τινι, ESCHL. <i>Ag. 1015 ;</i> εἴς τινα, EUR. <i>Hipp. 1264,</i> envers qqn.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Œc. 19, 19 ;</i> PLAT. <i>Ep. 309</i> a ; DÉM. <i>298 ;</i> <i>• Sup</i>. -ότατος, PLUT. <i>Mar. 2 ;</i> LUC. <i>D. mort. 12, 6</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. amārus, <i>sscr</i>. âmas, amas « cru ».</span></span><br><br>\n➁ <b>ὦμος, ου (ὁ) :<br>      1</b> épaule, IL. <i>2, 217, 259, 265 ; 3, 227, etc. ;</i> OD. <i>10, 362, etc. ;</i> ἐπ' ὤμου φέρειν, OD. <i>10, 170 ;</i> ἐπ' ὤμοις φέρειν, SOPH. <i>Tr. 564, etc. ;</i> ὤμοισι φορεῖν, IL. <i>19, 11 ;</i> ὤμοις φέρειν, SOPH. <i>fr. 401 ;</i> τοῖς ὤμοις καταφέρειν, PLUT. <i>Ant. 68 ;</i> ὤμῳ ἔχειν, IL. <i>14, 376 ;</i> ὤμοισιν ἔχειν, IL. <i>1, 45, etc. ;</i> ἐπ' ὤμων ἔχειν, SOPH. <i>fr. 342,</i> porter sur ses épaules ; ἀνὰ ὤμῳ ἔχειν, OD. <i>11, 128 ; 23, 275, m. sign. ;</i> ὤμῳ σάκος ἑλεῖν, IL. <i>15, 474,</i> prendre son bouclier sur son épaule ; ἐπ' ὤμοις τιθέναι, EUR. <i>Bacch. 754 ;</i> ἐπὶ τοὺς ὤμους ἐπιτιθέναι, NT. <i>Matth. 23, 4 ;</i> ἐπιτιθέναι τοῖς ὤμοις, HDN <i>4, 7, 12</i> placer sur ses épaules ; ἐλαύνειν φεύγοντα ὦμον, <i>etc</i>. IL. <i>5, 80, etc</i>. frapper l’épaule d’un fuyard ; <i>cf</i>. IL. <i>7, 16 ; 15, 341 ;</i> OD. <i>17, 462 ; au plur. pour le sg</i>. ἀμφὶ <i>ou</i> περὶ ὤμοισιν, autour de l’épaule, <i>en parl. du baudrier qui se passait sur l’épaule droite,</i> IL. <i>2, 45 ; 3, 334 ; 11, 29, etc. ;</i> OD. <i>8, 416 ; 2, 3 ; 4, 308 ; 20, 125 ;</i> SPT. <i>Esaï. 10, 27 ; invers. au sg. pour le plur</i>. IL. <i>1, 45, 46, etc. ;</i> OD. <i>10, 262, etc. ;</i> HÉS. <i>Sc. 468 ;</i> EUR. <i>Rhes. 305, Or. 1471, etc. ; au duel,</i> IL. <i>2, 217, 265 ; 5, 622 ; 15, 308, etc. ;</i> OD. <i>14, 277, etc. ; en parl. des animaux,</i> parties supérieures des pieds de devant, ARSTT. <i>H.A. 1, 15, 1, etc. ;</i> (chevaux, IL. <i>6, 510 ; 10, 333 ; 15, 267 ; 16, 468 ;</i> XÉN. <i>Eq. 1, 11 ; 8, 6 ;</i> lions, HÉS. <i>Sc. 430 ;</i> chiens, XÉN. <i>Cyn. 4, 1 ;</i> écrevisses, BATR. <i>298, etc.) ; en parl. des plantes, particul. dans un</i> cep de vigne, branche du milieu, GEOP. <i>4, 12, 4 ; 5, 22, 4 ; en parl. de vêtements,</i> SPT. <i>Ex. 28, 12 ; en parl. de chaises,</i> les côtés, SPT. <i>1Sam. 7, 33 ; fig. en parl. des côtés,</i> SPT. <i>Esaï. 60, 4 ; 66, 12 ; en mauv. part, au sens du franç</i>. « porter sur les épaules » SPT. <i>Num. 7, 9 ; cf</i>. SPT. <i>Esaï. 9, 6 ;</i><br><b>      2</b> <i>p. ext</i>. bras, HDT. <i>2, 121 ; 4, 62 ;</i> EUR. <i>Bacch. 1127 ;</i> SPT. <i>Malach. 2, 3 ; 2 Macc. 12, 35</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. umerus, <i>sscr</i>. amsas.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωμος - ὦμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5607":"<h1>on</h1>\n<p>Strong n° 5607 <i>Prononciation [oan]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être, étant, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὤν, οὖσα, ὄν</b>, <i>part. pr. de</i> .<br><br>\n➁ <b>ὦν</b>, <i>v</i>. .<br><br>\n➂ <b>ὧν</b>, <i>gén. pl. du relat</i>. , ἥ, ὅ.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ων - ὤν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe participe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n154 fois dans 149 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (8)</li>\n<li>Luc (15)</li>\n<li>Jean (26)</li>\n<li>Actes (31)</li>\n<li>Romains (18)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5608":"<h1>oneomai</h1>\n<p>Strong n° 5608 <i>Prononciation [o-neh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>acheter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠνέομαι</b>, <i>v</i>. ὠνέω.<br><br>\n<b>*ὠνέω</b>, acheter <span>(<i>seul. part. pf</i>. ἐωνηκώς)</span> ; <i>pass</i>. <span>(<i>impf</i>. ἐωνούμην, <i>ao</i>. ἐωνήθην, <i>pf</i>. ἐώνημαι, <i>pl.q.pf</i>. ἐωνήμην)</span> être acheté : <i>part. prés</i>. τὰ ὠνούμενα, PLAT. <i>Phæd. 69</i> b, les choses achetées ;<br><b><i>Moy</i>. ὠνέομαι-οῦμαι</b> <i>seul us. d’ord. au sens act</i>. <span>(<i>impf</i>. ἐωνούμην <i>ou</i> ὠνούμην, <i>f</i>. ὠνήσομαι, <i>ao</i>. ἐωνησάμην <i>ou</i> ὠνησάμην, <i>pf</i>. ἐώνημαι ; <i>les Att., au lieu de l’ao</i>. ἐωνησάμην, <i>emploient</i> ἐπριάμην, <i>v</i>. πρίαμαι)</span><br><b>   I</b> acheter, HÉS. <i>O. 343, etc. ; p. opp. à</i> πωλεῖν, vendre, HDT. <i>1, 165 ; 3, 139 ;</i> XÉN. <i>Ages. 1, 18 ; Mem. 2, 10, 4 ;</i> PLAT. <i>Leg. 741</i> b, <i>849</i> c, <i>etc. ; avec le n. de prix au gén</i>. HDT. <i>5, 6 ;</i> XÉN. <i>Cyr. 4, 5, 42 ;</i> AN. <i>3, 1, 20, etc. ;</i> τι ψυχῆς, HÉRACLITE ÉPH. <i>fr. 85</i> (PLUT. <i>M. 457</i> d) acheter qqe ch. au prix de sa vie ; <i>postér. au dat. :</i> τῷ θανάτῳ τὴν σωτηρίαν, NAZ. acheter son salut (éternel) par sa mort ; <i>avec le n. de provenance au gén. précédé d’une prép. :</i> τι παρά τινος, PLAT. <i>Prot. 313</i> e, <i>Leg. 849</i> d, <i>etc. ;</i> τινι, AR. <i>Ach. 815, Pax 1261 ; ou</i> ἀπό τινος, A. TAT. <i>5, 17,</i> acheter qqe ch. à qqn ; ἐξ ἀγορᾶς, XÉN. <i>An. 3, 2, 21 ;</i> ἐκ Κορίνθου, XÉN. <i>Hell. 7, 2, 17,</i> acheter à Corinthe ; <i>fig</i>. τὴν εὔνοιαν, DÉM. <i>164, 13,</i> acheter la bienveillance (de qqn) ; εἰρήνην, PLUT. <i>Per. 23,</i> acheter une paix ; σπονδάς, PLUT. <i>Sert. 6,</i> acheter un traité ; <i>en mauv. part :</i> τινα, DÉM. <i>122, 21 ; 123, 21 ; 309, 15 ;</i> PLUT. <i>Phil. 15,</i> acheter <i>ou</i> corrompre qqn ; ἀργύρου τινά, EUR. <i>Hec. 360,</i> acheter qqn à prix d’argent ; <i>particul. :</i><br><b>      1</b> prendre à ferme, affermer : τὰ τέλη, XÉN. <i>Vect. 4, 19, 20,</i> les impôts (<i>cf</i>. τελώνης) ; τὰ μέταλλα, DÉM. <i>435, 7,</i> les mines ; <i>avec le gén. du prix,</i> LYS. <i>108, 26 ;</i><br><b>      2</b> faire mine d’acheter, marchander, <i>acc</i>. HDT. <i>1, 68, 69, etc. ;</i> DÉM. <i>309, 15 ;</i> AND. <i>17, 28 ;</i><br><b>   II</b> écarter à prix d’argent : ἐγκλήματα, DÉM. <i>987, 7,</i> des accusations ; κίνδυνον, DÉM. <i>990, 17,</i> un danger ; <i>avec l’inf</i>. DÉM. <i>96,</i> obtenir à prix d’argent que, <i>etc. ; ou avec</i> ὅπως μή <i>et le sbj</i>. DÉM. <i>236,</i> obtenir à prix d’argent que… ne.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. part</i>. ἐωνηκώς, LYS. (<i>Bkk. 95, 25) ; pass. impf. 3 sg</i>. ἐωνεῖτο, XÉN. <i>Eq. 8, 2 ; ao</i>. ἐωνήθην, XÉN. <i>Mem. 2, 7, 12 ;</i> PLAT. <i>Leg. 850</i> a, <i>etc. ; pf</i>. ἐώνημαι, PLAT. <i>Ax. 366</i> c ; DÉM. <i>406, 11 ;</i> IS. <i>88, 21 ;</i> LYS. <i>165, 16 ; pl.q.pf. 3 sg</i>. ἐώνητο, AR. <i>Pax 1182. Les formes de temps second. sans augm. syllab. sont ion. : impf. 3 sg</i>. ὠνέετο, HDT. <i>3, 139 ; 3 pl</i>. ὠνέοντο, HDT. <i>1, 69 ; ttef</i>. ὠνούμην, LYS. <i>108, 36 ;</i> ὠνησάμην, HPC. <i>Epist. 1282, 23 ;</i> PLUT. <i>Nic. 10 ;</i> LUC. <i>Herm. 81, D. mort. 4, 1 ;</i> NT. <i>Ap. 7, 16 ; l’ao</i>. ὠνησάμην <i>au sens de</i> vendre, EUP. (ATH. <i>266</i> f) <i>postér. employé p</i>. ὠνάμην <i>Carel Gabriel Cobet, Variæ lectiones p. 137</i>.<br><span><b>Étym</b>. ὦνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωνεομαι - ὠνέομαι</font>\n<br><br>vient apparemment du mot primaire onos (une somme ou prix)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5609":"<h1>oon</h1>\n<p>Strong n° 5609 <i>Prononciation [o-on']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un œuf</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ᾠόν, οῦ (τὸ) :<br>   I</b> œuf, ARSTT. <i>H.A. 6, 2, etc. ;</i><br><b>      1</b> <i>au propre, particul</i>. œuf de poule, AR. <i>Lys. 856 ;</i> LUC. <i>M. cond. 26 ;</i> de crocodile, HDT. <i>2, 68 ;</i> de serpent, ARSTT. <i>H.A. 5, 34, 1 ;</i> de poisson, <i>etc</i>. HDT. <i>2, 93 ;</i> ARSTT. <i>H.A. 9, 3, etc. ;</i> ᾠὸν τίκτειν, HDT. <i>2, 68 ;</i> AR. <i>Av. 695, etc. ou</i> ἀφιέναι, ARSTT. <i>H.A. 6, 13, 6, etc</i>. pondre un œuf ; ἐκλέπειν, HDT. <i>2, 68,</i> faire éclore un œuf, <i>fig</i>. ᾠὸν ἅπας γέγονεν, ANTH. <i>11, 398,</i> il est devenu tout comme un œuf, <i>càd</i>. tout chauve ;<br><b>      2</b> <i>p. anal</i>. graine de plante, ARSTT. <i>G.A. 1, 23, 2 ;</i><br><b>   II</b> objet en forme d’œuf (vase, ATH. <i>503</i> f ; verre, HÉRON <i>dans</i> MATH. <i>p. 147</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. ὤϊον, SAPPH. <i>fr. 112 Bgk</i>.<br><span><b>Étym</b>. <i>p</i>. ὤιον, *ὤϝιον ; <i>cf. lat</i>. ovum.</span></span><br><br>\n➁ <b>ᾦον, ου (τὸ)</b> <i>lacon. c</i>. , CLÉARQ. (ATH. <i>57</i> e).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωον - ᾠόν</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5610":"<h1>hora</h1>\n<p>Strong n° 5610 <i>Prononciation [ho'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un certain temps défini ou saison fixée par la loi de la nature et qui revient avec une nouvelle année\n<ol type=\"a\">\n<li>les saisons de l'année, printemps, été, automne, hiver</li>\n</ol>\n</li>\n<li>l'heure du jour (limité par le lever et le coucher du soleil), un jour</li>\n<li>la douzième partie d'une journée, une heure, (les douze heures de la journée étant comptés du lever au coucher du soleil)</li>\n<li>tout temps défini, un instant, un moment</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὥρα, ας (ἡ) :<br>A</b> toute division du temps, période de temps :<br><b>   I</b> <i>selon la durée en gén</i>. temps, durée : ὥρα νυκτὸς καὶ μηνὸς καὶ ἐνιαυτοῦ, XÉN. <i>Mem. 4, 7, 4,</i> la durée d’une nuit et d’un mois et d’une année ; εἰς ὥραν ἔτους, PLUT. <i>M. 982</i> c, pour une durée d’une année, pour une année ; <i>au plur</i>. αἱ ὧραι τοῦ ἔτους, <i>ou</i> τοῦ ἐνιαυτοῦ, <i>ou</i> τῶν ἐνιαυτῶν, PLAT. <i>Conv. 188</i> a, les périodes de l’année, ὧραι καὶ ἐνιαυτός, PLAT. <i>Crat. 408</i> e ; les périodes de l’année et l’année ; περιτελλομέναις ὥραις, SOPH. <i>O.R. 156,</i> dans les périodes de temps qui accomplissent leur évolution ; ὁ κύκλος τῶν ὡρέων, HDT. <i>2, 4,</i> le cercle des saisons, <i>etc. ;</i><br><b>   II</b> <i>particul</i>. période déterminée du temps :<br><b>      1</b> année : τῆς ὥρης μέσον θέρος, HDT. <i>8, 12,</i> le milieu de l’été ; ἐν τῇ πέρυσιν ὥρᾳ, DÉM. <i>1283, 20,</i> l’année dernière ; ἐκ τῶν ὡρῶν εἰς τὰς ὥρας, AR. <i>Th. 950</i> d’années en années ;<br><b>      2</b> période du mois, XÉN. <i>Mem. 4, 7, 4 ;</i> PLAT. <i>Phil. 30</i> c, <i>Leg. 899</i> b, <i>etc. ;</i><br><b>      3</b> période du jour <i>ou</i> de la nuit ; ὧραι τῆς ἡμέρας, XÉN. <i>Mem. 4, 3, 4,</i> les heures de la journée ; δι' ὥραν ἡμέρας, DÉM. <i>1456, 8,</i> pendant la période de la journée, pendant le jour ; νυκτὸς ἐν ὥρῃ, HH. <i>Merc. 67, 155, 400,</i> pendant la période de la nuit, pendant la nuit ; <i>avec omiss. de</i> ἡμέρας <i>ou de</i> νυκτός : μέχρι τρίτου μέρους ὥρας, PLAT. <i>Leg. 784</i> a, jusqu’à la troisième partie du jour ; τῆς ὥρας μικρὸν πρὸ δύντος ἡλίου, XÉN. <i>Hell. 7, 2, 22,</i> le jour un peu avant le coucher du soleil ; τῆς ὥρας ἐγίγνετο ὀψέ, DÉM. <i>541 fin,</i> il se faisait tard ; πολλῆς ὥρας, POL. <i>5, 8, 3,</i> le jour étant avancé ; περὶ πολλὴν ὥραν, JOS. <i>A.J. 8, 4, 4,</i> à une heure avancée du jour ; μεσονυκτίοις ὥραις, ANACR. <i>31, 1,</i> au milieu de la nuit ; <i>p. suite,</i> heure : ἡ πρώτη, ἡ δευτέρα ὥρα SEXT. <i>M. 10, 182,</i> la première, la deuxième heure ; <i>d’ord. sans art</i>. τρίτης ὥρας, PLUT. <i>Rom. 12,</i> à la troisième heure ; ὀγδόης ὥρας, PLUT. <i>Alex. 60,</i> à la huitième heure ; <i>cf</i>. PLUT. <i>Æmil. 22, Syll. 38, etc. ; prov</i>. <span>δυωδεκάτης ὥρας</span>, PLUT. <i>Crass. 17,</i> à la douzième heure, <i>càd</i>. à la dernière heure, <i>en parl. de la mort imminente ;</i><br><b>   III</b> selon les saisons, <i>d’où :</i><br><b>      1</b> saison, HOM. ATT. ; ὥραι τετράμορφοι, EUR. <i>fr. 937,</i> les saisons aux quatre formes ; <i>Homère et Hésiode ne connaissent encore que trois</i> ὥραι : εἴαρος ὥρη, IL. <i>6, 148 ;</i> ὥρη εἰαρινή, IL. <i>2, 471 ; 16, 643 ;</i> OD. <i>18, 367 ; 22, 301 ;</i> HH. <i>Cer. 174 ;</i> ἦρος ὥρα, AR. <i>Nub. 1008 ;</i> ἦρος ὧραι, EUR. <i>Cycl. 506,</i> la saison du printemps ; <i>abs</i>. νέα ὥρα, AR. <i>Eq. 419,</i> la saison nouvelle, le printemps ; <i>abs</i>. ὥρῃ, OD. <i>9, 51,</i> au printemps ; <i>cf</i>. IL. <i>2, 468 ;</i> THC. <i>4, 6 ;</i> θέρεος ὥρη, HÉS. <i>O. 586,</i> la saison d’été ; <i>abs</i>. χειμῶνος ὥρα, PLUT. <i>Ant. 7, etc. ; ou</i> ὥρη χειμερίη, OD. <i>5, 485 ;</i> HÉS. <i>O. 496, etc</i>. la saison d’hiver ; <i>l’automne</i> (<i>v</i>. ὀπώρα) <i>n’est mentionné qu’à partir d’Alcman 64, et d’Hippocrate, 366</i> (<i>v</i>. φθινόπωρον <i>et</i> μετόπωρον) ; <i>particul</i>. la saison par excellence, saison des fleurs, printemps, IL. <i>2, 468 ;</i> OD. <i>9, 51 ; fig</i>. le printemps de la vie, la fleur de l’âge, ESCHL. <i>Sept. 517 ;</i> XÉN. <i>Conv. 3, 1 ;</i> οἱ ἐν ὥρᾳ, PLAT. <i>Rsp. 474</i> d ; PLUT. <i>M. 84</i> e, <i>Cam. 33, 34, etc. ; ou</i> ἐπὶ ὥρᾳ, PLAT. <i>Rsp. 474</i> e, ceux qui sont dans la fleur de l’âge ; εἶναι ἐν ὥρᾳ, PLAT. <i>Men. 76</i> b, être dans la fleur de l’âge ; ὥραν ἔχειν, ESCHL. <i>Suppl. 997, m. sign. ;</i> λήγειν ὥρας, PLAT. <i>1 Alc. 131</i> e, cesser d’être dans la fleur de l’âge ; <i>joint à</i> κάλλος, XÉN. <i>Mem. 2, 1, 22 ;</i> PLAT. <i>Phæd. 80</i> c, <i>etc. ;</i> φεῦ φεῦ τῆς ὥρας, τοῦ κάλλους ! AR. <i>Av. 1724,</i> ah ! que de grâce, que de beauté ! ;<br><b>      2</b> climat, température, HDT. <i>1, 142, 149, 277 ; 3, 106 ; 4, 199 ;</i> XÉN. <i>Cyn. 5, 5, etc. ;</i> PLAT. <i>Criti. 111</i> e, <i>Phæd. 111</i> b ;<br><b>      3</b> produit d’une saison, fruits, moisson, XÉN. <i>Hell. 2, 1, 1 ;</i> PLAT. <i>Epin. 977</i> b, <i>etc. ;</i><br><b>B</b> temps opportun, moment favorable, PD. <i>P. 4, 439 ; N. 4, 55 ;</i> XÉN. <i>Mem. 2, 1, 2, etc. ;</i> εἰς ὥρας, OD. <i>9, 135,</i> au moment convenable ; ἐν ὥρῃ, OD. <i>17, 176 ;</i> HDT. <i>1, 31 ;</i> ἐν ὥρᾳ, AR. <i>Vesp. 242,</i> à temps ; τὴν ὥρην, HDT. <i>2, 2 ; 8, 19 ;</i> τὴν ὥραν, XÉN. <i>Œc. 20, 16 ;</i> καθ' ὥραν, THCR. <i>Idyl. 18, 12, etc</i>. à temps <i>ou</i> au temps accoutumé ; παρ' ὥραν, THCR. <i>Epigr. 9, 1,</i> à contre-temps ; πρὸ τῆς ὥρας, XÉN. <i>Œc. 20, 16 ;</i> πρὸ ὥρας, LUC. <i>Luct. 13,</i> avant le temps ; <i>p. suite avec un rég</i>. temps d’une chose, moment convenable pour une chose : κοίτοιο, OD. <i>3, 334 ;</i> ὕπνου, OD. <i>11, 379,</i> l’heure du coucher, du sommeil ; δόρποιο, OD. <i>14, 407,</i> l’heure du repas ; ἀρότοιο, HÉS. <i>O. 460 ;</i> ἀμήτου, HÉS. <i>O. 575,</i> l’époque du labour, de la moisson ; <i>avec un inf. :</i> ὥρη (ἐστὶν) εὕδειν, OD. <i>11, 330, 373 ;</i> ὥρα ἐστὶ καθεύδειν, XÉN. <i>An. 1, 3, 11,</i> c’est l’heure de dormir ; <i>abs. avec un dat. et un inf</i>. il est temps pour moi d’aller, PLAT. <i>Theæt. 145</i> b ; <i>cf</i>. XÉN. <i>Cyr. 4, 5, 1 ; avec une prop. inf</i>. ESCHL. <i>Ch. 650 ;</i> SOPH. <i>O.R. 467, etc. ; particul</i>. âge nubile : εἰς ἀνδρὸς ὥραν, PLAT. <i>Criti. 111</i> b ; <i>ou</i> ἐς γάμου ὥρην ἀπικέσθαι, HDT. <i>6, 61,</i> être en âge de se marier ; <i>cf</i>. OD. <i>15, 126 ;</i> οὐκ οὖσαν αὐτῷ καθ' ὥραν παῖδα, PLUT. <i>Demetr. 14,</i> comme il n’avait pas de fille en âge de se marier ;<br><b>C</b> Ὧραι, ῶν (αἱ) IL. <i>5, 749, etc</i>. les Heures, <i>gardiennes des portes du ciel et servantes des dieux,</i> IL. <i>5, 749 ; 8, 393, 433 ; 21, 450 ; particul. servantes d’Aphrodite,</i> HH. <i>6, 5 et 12 ; au nombre de trois, Eunomia, Dikè et Eirènè, filles de Zeus et de Thémis, sel</i>. HÉS. <i>Th. 901 ; joint à</i> Χάριτες, HH. <i>Ap. 194 ;</i> HÉS. <i>O. 75</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ὥρη, HOM. HÉS. HDT. <i>ll. cc. gén. pl. ép</i>. ὡράων, PROCL. <i>H. Sol. 12 ; ion</i>. ὡρέων, HDT. <i>2, 4 ; gén. pl. dor</i>. ὡρᾶν, PD. <i>I. 2, 23 ; dat. pl. épq</i>. ὥραισιν, PD. <i>P. 9, 105 ;</i> NONN. <i>D. 42, 284, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *Hieh₁-r-, *Hioh₁-r- année ; <i>cf</i>. ὧρος, <i>angl</i>. year.</span></span><br><br>\n➁ <b>ὤρα, ας (ἡ)</b> soin, souci, sollicitude, HÉS. <i>O. 30 ;</i> TYRT. <i>7, 11 ;</i> ὤραν τινὸς ἔχειν, HDT. <i>1, 4 ; 3, 155 ;</i> SOPH. <i>O.C. 386 ; ou</i> ποιεῖσθαι, HDT. <i>9, 8,</i> avoir <i>ou</i> prendre soin de qqn <i>ou</i> de qqe ch. ; ὑπέρ τινος, EL. <i>1, 59, m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ὤρη, HÉS. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>p</i>. *ϝώρα, <i>de la R. indo-europ</i>. *uer-, observer, noter, prendre soin de ; <i>cf</i>. ὁράω, οὖρος 3.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωρα - ὥρα</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n108 fois dans 100 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (23)</li>\n<li>Marc (12)</li>\n<li>Luc (16)</li>\n<li>Jean (26)</li>\n<li>Actes (12)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Philémon (1)</li>\n<li>1 Jean (2)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G5611":"<h1>horaios</h1>\n<p>Strong n° 5611 <i>Prononciation [ho-rah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fleurissant, beau, belle (utilisé pour le corps humain)</li>\n<li>qui vient à son heure, qui arrive au moment favorable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὡραῖος, α, ον :<br>   I</b> qui est de la saison : ὡραῖος βίος, HÉS. <i>O. 32, ou</i> βίοτος, HÉS. <i>O. 305,</i> provisions de la saison, <i>càd</i>. fruits de la saison ; τὰ ὡραῖα, THC. <i>1, 120 ;</i> XÉN. <i>An. 5, 3, 9 ; Œc. 15, 1, etc. ;</i> PLAT. <i>Leg. 845</i> e, <i>847</i> e, <i>etc</i>. les fruits de la saison ;<br><b>   II</b> qui se fait à une époque <i>ou</i> dans une saison déterminée : ἄροτος ὡραῖος, HÉS. <i>O. 618,</i> labour fait en temps convenable ; ἔργον ὡραῖον, HÉS. <i>O. 644,</i> travail accompli au moment convenable ; πλόος ὡραῖος, HÉS. <i>O. 632, 667,</i> navigation entreprise en temps convenable ; τάριχος ὡραῖον, ARÉT. <i>p. 120</i> c ; HÉS. (ATH. <i>116</i> b), <i>etc</i>. salaison préparée en temps convenable ; <i>subst</i>. ἡ ὡραία, la saison où se fait d’ord. telle ou telle chose, <i>particul</i>. la saison de la moisson <i>ou</i> de la récolte : ἐς ὡραίην, A. RH. <i>3, 1390 ; ou</i> περὶ τὴν ὡραίην, PAUS. <i>4, 10,</i> vers l’époque de la moisson ; la saison où l’on se met soit en mer, DÉM. <i>1292, 5,</i> soit en campagne, DÉM. <i>123, 16 ;</i> POL. <i>3, 16, 7 ; 3, 41, 2 ; ailleurs</i> la saison des pluies : τὴν ὡραίαν οὐκ ὕει, HDT. <i>4, 28,</i> il ne pleut pas à l’époque ordinaire des pluies ; τὰ ὡραῖα, <i>c</i>. καταμήνια, HPC. <i>266, 30 ;</i> βίος ὡραῖος, EUR. <i>Ph. 968,</i> vie mûre pour la mort ; θάνατος ὡραῖος, XÉN. <i>Ages. 10, 3,</i> mort à l’âge régulier ; <i>p. suite :</i><br><b>      1</b> qui est de saison, qui arrive à point, mûr, opportun : ὡραῖος ἐτελεύτησε, PLUT. <i>Cam. 43 ; ou</i> ἀποτέθνηκε, PLUT. <i>M. 178</i> d, il mourut en âge de mourir ; <i>particul</i>. mûr pour le mariage, <i>en parl. des hommes,</i> HÉS. <i>O. 695 ;</i> ὡραία γάμου <i>ou</i> γάμων, HDT. <i>1, 196 ; 6, 122 ;</i> XÉN. <i>Cyr. 4, 6, 9,</i> mûre pour le mariage, nubile ; <i>avec un gén. de pers. :</i> ὡραία ἀνδρός, HDT. <i>1, 107,</i> jeune fille mûre pour un mari ;<br><b>      2</b> convenable, régulier, légitime : ὡραῖα ἱερά, PLAT. <i>Criti. 116</i> c, sacrifices ordinaires ; ὡραίων τυχεῖν, EUR. <i>Suppl. 175,</i> obtenir <i>ou</i> recevoir les honneurs dus ;<br><b>   III</b> qui est dans la fleur de l’âge, <i>en parl. des jeunes gens,</i> LUC. <i>Alex. 41 ;</i> οἱ καλοὶ καὶ ὡραῖοι, XÉN. <i>Conv. 7, 3 ;</i> PLUT. <i>Ages. 2, M. 766</i> b ; <i>p. suite,</i> beau, gracieux, charmant, <i>en parl. de jeunes gens, d’enfants,</i> XÉN. <i>Conv. 2, 1, etc. ;</i> PLAT. <i>Rsp. 574</i> c ; <i>en parl. de femmes,</i> AR. <i>Ran. 291 ; de petites filles,</i> AR. <i>Ach. 1148, etc. ; joint à</i> καλός, XÉN. <i>Conv. 8, 21 ;</i> PLUT. <i>M. 778</i> a, <i>etc. ; p. suite,</i> qui concerne des jeunes gens <i>ou</i> des enfants, XÉN. <i>Conv. 4, 26</i>.<br><span>•<i> Sup</i>. ὡραιότατος, XÉN. <i>Mem. 1, 3, 14 ;</i> AR. <i>Ran. 291, etc. ;</i> ὡραιέστατος, EPICH. (EUST. <i>p. 1441</i>).<br><span><b>Étym</b>. ὥρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωραιος - ὡραῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5612":"<h1>oruomai</h1>\n<p>Strong n° 5612 <i>Prononciation [o-roo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rugir, hurler (d'un lion, loup, chien, et autres bêtes)\n<ol type=\"a\">\n<li>d'hommes : pousser un cri fort et inarticulé, de douleur ou de joie</li>\n</ol>\n</li>\n<li>chanter d'une voix forte</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠρύω</b> <span>[ῡ]</span> ANTH. <i>11, 31, d’ord. moy</i>. <b>ὠρύομαι</b> <span>(<i>seul. prés. et impf. et ao</i>. ὠρυσάμην)</span> <span>[ῡ]</span><br><b>   I</b> hurler, <i>en parl. des loups et des chiens,</i> THCR. <i>Idyl. 2, 35 ;</i> COL. <i>116 ;</i> DS. <i>1, 87 ;</i> rugir, <i>en parl. de lions,</i> A. RH. <i>4, 1389 ;</i> CALL. <i>fr. 423 ; en parl. d’animaux en gén</i>. PLUT. <i>M. 973</i> a ; <i>avec un acc. neutre,</i> THCR. <i>Idyl. 1, 71 ; p. ext. en parl. de l’homme,</i> PD. <i>O. 9, 163 ;</i> PLAT. COM. (ATH. <i>628</i> c) ; <i>en parl. des flots de la mer,</i> ANTH. <i>11, 31 ;</i> DP. <i>83 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> pousser des hurlements de douleur, HDT. <i>3, 117 ;</i> SPT. <i>Ps. 38, 8 ;</i> ἐπί τινι, LUC. <i>D. mort. 10, 13 ;</i> περί τινα, BION <i>1, 18,</i> au sujet de qqn ; τινα, THCR. <i>Idyl. 1, 71,</i> pousser des hurlements de douleur au sujet de qqn ;<br><b>      2</b> pousser des cris de joie véhéments, HDT. <i>4, 75</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. seul. prés. part</i>. SIB. <i>8, 240 ;</i> <span>[ῠ]</span> PLAT. COM. <i>l. c. ;</i> DP. <i>83</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₃reuH-, hurler, rugir ; <i>cf. sscr</i>. rauti, ruváti, <i>lat</i>. rūmor, ravis, raucus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωρυομαι - ὠρύομαι</font>\n<br><br>vient apparemment d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5613":"<h1>hos</h1>\n<p>Strong n° 5613 <i>Prononciation [hoce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>comme, selon ce que, d'une façon semblable, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὠς</b>, <i>barbarisme d’un Scythe pour</i> ὡς, AR. <i>Th. 1192, 1210, 1212, 1214</i>.<br><br>\n➁ <b>ὦς, ὠτός (τὸ)</b> <i>dor. c</i>. , THCR. <i>Idyl. 11, 32</i>.<br><br>\n➂ <b>ὡς</b>, <i>adv. et conj. :</i><br><b>A</b> <i>adv. relat. marquant :</i><br><b>   I</b> <i>une comparaison :</i><br><b>      1</b> comme, de même que, <i>en corrélat. avec un antécéd. exprimé :</i> ὡς…, ὥς, IL. <i>1, 512, etc</i>. comme…, ainsi ; de même que…, de même ; ὡς δέ…, ὥς, IL. <i>5, 161 ; 11, 113 ; 22, 93, etc., m. sign. ;</i> ὡς…, τώς, ESCHL. <i>Sept. 465 ;</i> ὡς…, οὕτω, IL. <i>13, 825 ;</i> SOPH. <i>Ant. 421, Tr. 1132, m. sign. ;</i> ὧδε…, ὡς, SOPH. <i>Ant. 1108,</i> ainsi… que ; οὕτως…, ὡς, SOPH. <i>El. 802 ;</i> XÉN. <i>An. 7, 1, 17, etc. ;</i> αὕτως…, ὡς, SOPH. <i>Tr. 1039, m. sign. ; l’antécéd. peut être s.-e. :</i> κινήθη δ' ἀγορὴ ὡς κύματα μακρὰ θαλάσσης, IL. <i>2, 144,</i> l’assemblée fut agitée comme les longs flots de la mer ; <i>dans la prop. à laquelle il appartient</i> ὡς <i>se construit avec un verbe soit à l’ind. prés. :</i> ὡς δ' ἄνεμος ἄχνας φορέει…, ὣς τότ' Ἀχαιοί, <i>etc</i>. IL. <i>5, 499,</i> comme le vent emporte la paille, ainsi alors les Grecs, <i>etc. ; cf</i>. IL. <i>9, 4 ; 16, 364 ; ou à l’ind. ao</i>. IL. <i>3, 33 ; 4, 275 ; 16, 823, etc. ; soit au sbj. prés. ou ao. :</i> ὡς δὲ δράκων ἄνδρα μένῃσιν…, ὣς Ἕκτωρ, <i>etc</i>. IL. <i>22, 93,</i> comme un serpent attend un homme, ainsi Hector ; <i>cf</i>. IL. <i>5, 161 ; 10, 183, 485 ; 13, 314 ; dans ce cas qqf. avec</i> ἄν : ὡς δ' ὅτ' ἄν, IL. <i>11, 269 ; 17, 520 ; elliptiq. ὡς peut se construire avec un suj. sans verbe :</i> ὡς κύων νεϐρὸν ἐκμαστεύομεν, ESCHL. <i>Eum. 247,</i> ainsi comme le chien poursuit un faon nous poursuivons le sang, <i>etc. ; dans ce cas, il se place souv. après le suj. et s’écrit</i> ὥς : θεὸς δ' ὣς τίετο, IL. <i>5, 78,</i> il était honoré comme un dieu ; βόες ὣς ἀγελαῖαι, OD. <i>22, 299,</i> comme un troupeau de génisses ; <i>cf</i>. OD. <i>6, 20 ; 15, 479, etc. ; en ce sens ὡς est qqf. pléonast. :</i> ἔλαυνεν ὡς οὐκ ἀΐοντι ἐοικώς, IL. <i>23, 430,</i> il poussait ses chevaux comme s’il n’entendait pas, <i>litt</i>. comme semblable à un homme qui n’entend pas ; <i>invers. dans ces sortes de comparaisons ὡς est qqf. omis :</i> κεῖνος Ἄτλας οὐρανῷ προσπαλαίει, PD. <i>P. 4, 515,</i> (comme) Atlas, celui-ci heurte le ciel, <i>càd</i>. autre Atlas, il heurte le ciel ; — <i>avec un subst. accompagné d’un adj. :</i> ὡς ποιμὴν ἀγροϐότας, SOPH. <i>Ph. 214,</i> comme un berger qui fait paître ses troupeaux dans les champs ; σύες ὣς ἀργιόδοντες, OD. <i>11, 413,</i> comme des porcs aux dents blanches ; — <i>avec un pron. :</i> ὡς ἐγώ, SOPH. <i>O.R. 60,</i> comme moi ; — <i>suivi de</i> ὅτε : ἤριπε δ' ὡς ὅτε τις δρῦς ἤριπε, IL. <i>13, 389,</i> il tomba comme lorsque tombe un chêne ; <i>cf</i>. IL. <i>2, 394 ; avec ellipse du verbe après</i> ὡς ὅτε : ἤριπε δ' ὡς ὅτε πύργος, IL. <i>4, 462,</i> il tomba comme lorsque tombe une tour ;<br><b>      2</b> comme, tandis que, en même temps que : ὡς ἥψατο γούνων, ὥς, <i>etc</i>. IL. <i>1, 512,</i> comme elle avait touché ses genoux, de même, <i>etc. ;</i> ὡς ἴδεν, ὥς, <i>etc</i>. IL. <i>14, 294,</i> dès qu’il la vit, aussitôt, <i>etc. ;</i> ὡς πρὸς ἀστρονομίαν ὄμματα πέπηγεν, ὣς πρὸς ἐναρμόνιον φορὰν ὦτα παγῆναι, PLAT. <i>Rsp. 530</i> d, en même temps que ses yeux sont fixés vers le cours des astres, les oreilles sont immobiles, tendues vers les accords qui leur arrivent ;<br><b>      3</b> tandis que, tant que, aussi longtemps que : ὡς ἂν οὗτος ἥλιος αἴρῃ, SOPH. <i>Ph. 1330,</i> aussi longtemps que ce soleil s’élèvera dans le ciel ; ὡς ἂν ᾖς οἷόσπερ εἶ, SOPH. <i>Aj. 1117,</i> tant que tu seras tel que tu es ; <i>postér. au sens de</i> ἕως, NT. <i>Joh. 12, 35, 36, etc. ;</i><br><b>      4</b> comme, autant que : ἑλὼν κρέας ὥς οἱ χεῖρες ἐχάνδανον, OD. <i>17, 344,</i> ayant pris de la viande autant que ses mains en pouvaient contenir ; ὡς εἶχε ποδῶν (<i>v</i>. πούς) autant qu’il avait de vitesse ; τὼς δέ σ' ἀπεχθήρω, ὡς νῦν σ' ἔκπαγλ' ἐφίλησα, IL. <i>3, 415,</i> et que je te haïsse autant que je t’ai étrangement aimée jusqu’à présent ; <i>cf</i>. HH. <i>Cer. 172 ;</i> SOPH. <i>O.C. 1124, etc. ; particul. après</i> ἤ <i>construit avec un comparat. :</i> βραχύτερα ἠκόντιζον ἢ ὡς ἐξικνεῖσθαι τῶν σφενδονητῶν, XÉN. <i>An. 3, 3, 7,</i> ils ne lançaient pas leurs javelots assez loin pour pouvoir atteindre les frondeurs ; <i>avec omiss. de</i> ἤ : μᾶσσον ὡς ἐμοὶ γλυκύ, ESCHL. <i>Pr. 630,</i> plus qu’il ne m’est agréable ; προθυμότερον ὡς, LYS. <i>111, 6,</i> avec plus d’empressement que, <i>etc. ;</i> PLAT. <i>Rsp. 526</i> c ; DÉM. <i>25, 53, etc. ; ;</i><br><b>   II</b> <i>une relation :</i><br><b>      1</b> comme, de la façon que : οὕτω νῦν καὶ ἐγὼ νοέω ὡς σὺ ἐΐσκεις, OD. <i>4, 148,</i> moi aussi je pense maintenant comme tu penses toi-même ; οὕτως ὡς πάντες ἐπίστασθε, XÉN. <i>An. 7, 1, 17,</i> ainsi que vous le savez tous ; <i>ou simpl. :</i> ὡς πάντες ἐπιστάμεθα, XÉN. <i>Hier. 10, 4,</i> comme nous le savons tous ;<br><b>      2</b> comme, selon que, suivant que : ὡς ὁ μάντις φησίν, ESCHL. <i>Sept. 24,</i> selon ce que dit le devin ; ὡς φάτις ἀνδρῶν, SOPH. <i>Ant. 828,</i> comme disent les hommes ; τὴν ἐπιστολὴν δίδωσι πιστῷ ἀνδρί, ὡς ᾤετο, XÉN. <i>An. 1, 6, 3,</i> il donne la lettre à un homme sûr, pensait-il (<i>litt</i>. selon ce qu’il pensait) ; <i>avec un gén. abs. :</i> προηγόρευε τὰ μὲν ποιεῖν, τὰ δὲ μὴ ποιεῖν, ὡς τοῦ δαιμονίου προσημαίνοντος, XÉN. <i>Mem. 1, 1, 4,</i> il conseillait de faire ceci, de ne pas faire cela, selon que la divinité le signifiait d’avance ; <i>avec l’inf. dans une prop. dépendant d’une prop. subordonnée :</i> ὡς σφίσι δοκέειν, HDT. <i>2, 124, etc</i>. selon leur avis ; <i>après</i> ὥς φησιν, ὡς λέγουσιν, ὡς οἶμαι <i>et autres constructions de ce genre, le verbe de la prop. principale devient comme le rég. de ces verbes et peut se construire à l’inf. :</i> ὡς δὲ Σκύθαι λέγουσι νεώτατον ἁπάντων ἐθνέων εἶναι τὸ σφέτερον (<i>pour</i> ἐστίν, ὡς λέγουσι) HDT. <i>4, 5,</i> la nation des Scythes, selon ce qu’ils disent eux-mêmes, est la plus récente de toutes ; <i>cf</i>. HDT. <i>1, 58, 65 ;</i> ἀνὴρ ὅδ' ὡς ἔοικεν οὐ νέμειν (<i>pour</i> οὐ νέμει, ὡς ἔοικε), SOPH. <i>Tr. 17, 38,</i> cet homme, à ce qu’il paraît, n’accorde pas, <i>etc. ;</i> ὡς γὰρ ἤκουσα εἶναι αὐτόν, HDT. <i>4, 76,</i> car, à ce que j’ai appris, il est, <i>etc. ; la prop. commençant par ὡς peut être la dernière :</i> ἐκφυγεῖν ἄνακτ' ὡς ἀκούομεν (<i>pour</i> ἐξέφυγεν ὡς ἀκούομεν) ESCHL. <i>Pers. 557,</i> le roi s’est enfui, comme nous l’apprenons ; <i>la prop. principale peut être construite avec</i> ὅτι : ὡς γὰρ ἤκουσά τινος ὅτι, XÉN. <i>An. 6, 2, 18,</i> car, comme je l’ai entendu dire, <i>etc. ;</i><br><b>      3</b> en tant que, autant que, dans la mesure où, <i>avec une nuance d’indétermination : ellipt. dans les locut</i>. ὡς ἕκαστος, ὡς ἕκαστοι, HDT. <i>1, 29, 114 ;</i> THC. <i>1, 3, etc</i>. chacun pour soi, <i>litt</i>. selon que chacun, <i>etc. ; d’ord. avec l’inf. :</i> ὡς ἐμὲ εὖ μεμνῆσθαι, HDT. <i>2, 125,</i> autant qu’il m’en souvient bien ; ὥς γέ μοι δοκεῖν, AR. <i>Pl. 736,</i> autant qu’il me semble ; ὡς σάφ' εἰκάσαι, SOPH. <i>O.C. 16,</i> autant qu’on le peut clairement conjecturer ; οὐκέτι πολλὸν χωρίον ὡς εἶναι Αἰγύπτου, HDT. <i>2, 8,</i> l’espace n’est plus assez grand pour qu’on l’appelle Égypte (<i>litt</i>. en tant que cela était de l’Égypte) μεγάλα ἐκτήσατο χρήματα ὡς ἂν εἶναι Ῥοδώπι, HDT. <i>2, 135,</i> elle acquit de grandes richesses pour une (femme comme) Rhodôpis ; <i>elliptiq</i>. ὡς ἐμοί, SOPH. <i>Ant. 1146 ;</i> PLAT. <i>Soph. 226</i> c ; <i>ou</i> ὥς γ' ἐμοί (<i>s.-e</i>. δοκεῖν) ATT. autant qu’il me semble ; ὡς ἐμῇ δόξῃ, XÉN. <i>Vect. 5, 2,</i> à mon avis ; εἶ γενναῖος ὡς ἰδόντι, SOPH. <i>O.C. 76,</i> à te voir, tu es d’un sang généreux ; <i>particul. dev. une prép. :</i> ὡς ἀπ' ὀμμάτων (<i>s.-e</i>. εἰκάσαι) SOPH. <i>O.C. 15,</i> à en juger par les yeux ; ὡς ἐκ τῶν δυνατῶν, THC. <i>2, 3,</i> autant que cela est possible ; ὡς ἐκ τῶν ὑπαρχόντων, THC. <i>7, 76,</i> eu égard aux circonstances ; ὡς τὸ πολύ, PLAT. <i>Rsp. 330</i> c ; ὡς ἐπὶ τὸ πολύ, PLAT. <i>Rsp. 377</i> b, le plus souvent ; ὡς ἐπὶ πλεῖστον, THC. <i>2, 35,</i> le plus possible ; ὡς ἐπὶ τὸ πλῆθος, PLAT. <i>Rsp. 364</i> a ; ὡς πλήθει, PLAT. <i>Rsp. 389</i> d, pour la plus grande part ; ὡς τὸ ἐπίπαν, HDT. <i>7, 50,</i> en général ; ἦσαν ὡπλισμένοι ὡς ἐν ὄρεσιν ἱκανῶς πρὸς τὸ ἐπιδραμεῖν, XÉN. <i>An. 4, 3, 31,</i> ils étaient armés de manière à pouvoir facilement courir, et fuir dans les montagnes ; ὡς πρὸς τὸ μέγεθος τῆς πόλεως, THC. <i>3, 113,</i> eu égard à la grandeur de la ville. <i>À cette construct. se rattache l’emploi de ὡς dev. un adv. :</i> ὡς ἀληθῶς, PLAT. <i>Phædr. 234</i> e, <i>etc</i>. aussi véritablement que possible ; ὡς ἐτύμως, ESCHL. <i>Eum. 534 ;</i> ὡς ἐτητύμως, SOPH. <i>El. 1444, m. sign. ; avec inversion :</i> θαυμαστῶς ὡς, PLAT. <i>Phæd. 92</i> a ; θαυμασίως ὡς, ATT. étonnamment ; ὑπερφυῶς ὡς, PLAT. <i>Gorg. 496</i> c, <i>Conv. 173</i> c, extraordinairement, prodigieusement ; θαυμαστῶς ὡς παρὰ δόξαν, PLAT. <i>Phæd. 95</i> a, d’une façon étrangement paradoxale ; ὑπερφυῶς δὴ τὸ χρῆμα ὡς, PLAT. <i>2 Alc. 147</i> c, chose extraordinaire, certes ! <i>Cette construct. se rencontre qqf. avec un compar. :</i> ὡς ἀληθεστέρως, PLAT. <i>Rsp. 347</i> e, en toute vérité ; ὡς ἑτέρως, PLAT. <i>Phædr. 276</i> c, tout autrement ; <i>surt. avec un superl. :</i> ὡς μάλιστα, ATT. le plus possible ; ὡς τάχιστα, ATT. le plus promptement possible ; ὡς βέλτιστος, ATT. le meilleur possible ; <i>avec la locut. complète :</i> ὡς ἠδύναντο ἀδηλότατα, THC. <i>7, 50,</i> le plus secrètement possible ; ὡς ἂν δυνώμεθα κράτιστα, XÉN. <i>An. 3, 2, 6,</i> le plus courageusement possible ; ὡς οἷόν τε μάλιστα, PLAT. <i>Rsp. 527</i> b, le plus possible ; <i>qqf. avec</i> ὡς <i>suivi de</i> ὅτι : ὡς ὅτι βέλτιστον, PLAT. <i>Conv. 218</i> d, le mieux possible ; <i>ou avec une prép. :</i> ὡς ἐς ἐλάχιστον χωρίον, THC. <i>1, 63,</i> sur l’espace le plus resserré possible ; ὡς ἐν βραχυτάτοις, ANT. <i>113, 21,</i> le plus brièvement possible ; ὡς ἐν ἐχυρωτάτῳ, XÉN. <i>Cyr. 1, 6, 26,</i> dans la situation la plus forte possible ;<br><b>   III</b> <i>l’intention, le but :</i><br><b>      1</b> avec l’intention de, dans le dessein de, en vue de, <i>avec un part. fut. :</i> ἐλάμϐανε τὸ τόξον ὡς κατατοξεύσων αὐτόν, HDT. <i>3, 36,</i> il prenait son arc afin de le frapper d’une flèche ; συλλαμϐάνει Κῦρον ὡς ἀποκτενῶν, XÉN. <i>An. 1, 1, 3,</i> il fait arrêter Cyrus pour le tuer ; παρεσκευάζοντο ὡς πολεμήσοντες, THC. <i>2, 7,</i> ils se préparaient en vue de faire la guerre ; <i>avec un part. abs. au gén. ou au nom. :</i> προσέθηκε δρέπανα, ὡς ἐμϐαλούντων εἰς τοὺς ἐναντίους, XÉN. <i>Cyr. 6, 1, 17,</i> il ajouta des faux pour qu’ils pussent se jeter sur l’ennemi ; δρέπανα περὶ τοῖς ἄξοσι προσήρμοσται ὡς ἐλῶντες καὶ οὗτοι εἰς τὰς τάξεις, XÉN. <i>Cyr. 6, 2, 17,</i> en outre des faux sont ajustées aux essieux pour que ces combattants puissent eux aussi s’élancer dans les rangs ;<br><b>      2</b> comme, en guise de : ὡς σιτίον καὶ φάρμακον διδόναι, XÉN. <i>An. 4, 2, 17,</i> donner même du poison en guise d’aliment ; <i>avec un part</i>. δεδίασιν ὡς εἰδότες, PLAT. <i>Ap. 29</i> a, ils craignent comme s’ils savaient ; εὔχονται ἀεὶ ὡς ἄθλιοι ὄντες ἀποθανεῖν, XÉN. <i>Cyr. 5, 1, 7,</i> ils souhaitent sans cesse de mourir, se trouvant malheureux ; ὡς εἰς Πισίδας βουλόμενος στρατεύεσθαι, XÉN. <i>An. 1, 1, 11,</i> disant qu’il voulait faire une expédition en Pisidie ; <i>avec un part. abs. au nom. :</i> ἐξ ὀμμάτων δ' ἤστραπτε γοργωπὸν σέλας, ὡς τὴν Διὸς τυραννίδ' ἐκπέρσων βίᾳ, ESCHL. <i>Pr. 356,</i> ses yeux étincelaient d’un éclat terrible, à l’idée qu’il allait détruire la domination de Zeus ; <i>avec une prép</i>. συσκευάζεσθαι ὡς εἰς στρατείαν, XÉN. <i>Hell. 3, 4, 11,</i> faire leurs préparatifs comme pour une expédition ; ἀπέπλεον ὡς ἐς τὰς Ἀθήνας, THC. <i>6, 61,</i> ils partirent faisant voile comme pour aller à Athènes ; ἀνήγοντο ὡς ἐπὶ ναυμαχίαν, XÉN. <i>Hell. 1, 1, 8,</i> ils gagnèrent la haute mer comme pour un combat naval ; φρύγανα συλλέγοντες ὡς ἐπὶ πῦρ, XÉN. <i>An. 4, 3, 11,</i> ramassant des broussailles pour allumer du feu ;<br><b>      3</b> en qualité de, <i>avec un subst. ou un adj. :</i> ὡς πολεμίοις αὐτοῖς χρῶνται, XÉN. <i>Cyr. 3, 1, 22,</i> ils les traitent en ennemis ; <i>cf</i>. XÉN. <i>Cyr. 3, 2, 25 ;</i> ἦν δὲ οὐδὲ ἀδύνατος ὡς Λακεδαιμόνιος εἰπεῖν, THC. <i>4, 84,</i> il n’était même pas incapable de parler pour un Lacédémonien, <i>càd</i>. il ne manquait pas d’éloquence ; ὡς γυνή, SOPH. <i>O.R. 1078,</i> en qualité de femme ; μακρὰν ὡς γέροντι ὁδόν, SOPH. <i>O.C. 20,</i> longue route pour un vieillard ; <i>cf</i>. SOPH. <i>O.C. 385, Ant. 62 ; avec</i> ἄν : ὡραῖον παῖδα ὡς ἂν Αἰγύπτιον, EL. bel enfant pour un Égyptien ; <i>p. suite avec un part</i>. parce que, vu que, attendu que : κατεγέλων τῆς πολιορκίας ὡς ἔχοντες τὰ ἐπιτήδεια, XÉN. <i>Cyr. 7, 5, 13,</i> ils se moquaient du siège, parce qu’ils avaient les provisions nécessaires ; θαυμάζονται ὡς σοφοὶ γεγενημένοι, XÉN. <i>Cyr. 1, 1, 1,</i> ils sont admirés comme ayant été sages ; ὡς οἰόμενος εἰδέναι, THC. <i>6, 32,</i> parce qu’il croyait savoir ; <i>avec un part. abs. au gén. ou à l’acc. :</i> παρήγγειλεν αὐτοῖς παρασκευάζεσθαι ὡς μάχης ἐσομένης, XÉN. <i>Hell. 7, 5, 20,</i> il leur ordonna de se préparer, parce que le combat allait commencer ; ὡς ἀδύνατον ὄν, ATT., parce que cela est impossible ; <i>la prop. commençant par ὡς exprime souv. non un fait, mais une simple possibilité, une conjecture, une opinion :</i> ἀγανακτοῦσιν ὡς μεγάλων τινῶν ἀπεστερημένοι (<i>càd</i>. ἡγούμενοι μεγάλων τινῶν ἀπεστερῆσθαι) PLAT. <i>Rsp. 329</i> a, ils s’indignent estimant qu’ils sont privés de grands biens ; διέϐαλλον ὡς λυμαινόμενον τὴν πολιτείαν, XÉN. <i>Hell. 2, 3, 16,</i> ils l’accusaient de perdre l’État ; αἰτεῖ αὐτοῦ μισθὸν ὡς οὕτω περιγενόμενος ἂν τῶν ἀντιστασιωτῶν, XÉN. <i>An. 1, 1, 10,</i> il lui demanda une solde, se faisant fort de pouvoir ainsi triompher de la faction contraire ; λέγουσιν ἡμᾶς ὡς ὀλωλότας, ESCHL. <i>Ag. 672,</i> ils parlent de nous comme si nous étions morts ; ὡς μηδὲν εἰδότ' ἴσθι μ' ὧν ἀνιστορεῖς, SOPH. <i>Ph. 253,</i> sache que je ne sais rien des choses que tu rappelles ; <i>avec un part. abs. au gén. ou à l’acc. :</i> νῦν δέ, ὡς οὕτως ἐχόντων, στρατιὴν ἐκπέμπετε, HDT. <i>8, 144,</i> et maintenant, les choses étant ainsi, faites partir au plus vite l’armée ; ἐρώτα ὅ τι βούλει ὡς τἀληθῆ ἐροῦντος, XÉN. <i>Cyr. 3, 1, 9,</i> demande ce que tu veux, sûr que je dirai la vérité (<i>comme s’il y avait</i> πιστεύων με ἐρεῖν) ; μισθὸν αἰτοῦσιν ὡς οὐχὶ αὐτοῖσιν ὠφέλειαν ἐσομένην, PLAT. <i>Rsp. 345</i> e, ils demandent un salaire, estimant qu’il n’y aura pour eux aucun avantage (<i>comme s’il y avait</i> ἡγούμενοι ὡς οὐχὶ ὠφέλεια ἔσται) ; <i>cf</i>. THC. <i>7, 25 ;</i> PLAT. <i>Rsp. 604</i> b, <i>etc. ;</i> SOPH. <i>Aj. 281 ;</i><br><b>      4</b> en quelque sorte, à peu près, environ, <i>litt</i>. comme (si c’était), comme (qui dirait) : ὡς τὸ τρίτον μέρος, THC. le tiers environ, <i>litt</i>. comme le tiers ; ὡς δύο παρασάγγας, XÉN. <i>Cyr. 6, 3, 10,</i> environ deux parasanges ; ἀπέθανον ὡς πεντακόσιοι, XÉN. <i>An. 1, 6, 1,</i> environ cinq cents moururent ; σὺν ἀνθρώποις ὡς εἴκοσι, XÉN. <i>An. 3, 3, 5,</i> avec vingt hommes environ ; <i>avec l’addit. de</i> μάλιστα : ὡς πέντε μάλιστα, HDT. <i>7, 30,</i> environ cinq ; <i>de même avec des mots formés d’un n. de nombre :</i> παῖς ὡς ἑπταετής, PLAT. <i>Gorg. 471</i> c, un enfant d’environ sept ans ; δρέπανα ὡς διπήχη, XÉN. <i>Cyr. 6, 1, 30,</i> des faux d’environ deux coudées ; <i>cf</i>. XÉN. <i>An. 5, 4, 12 ;</i><br><b>   IV</b> <i>une exclamation : avec un adj. :</i> ὡς ἄνοον κραδίην ἔχες, IL. <i>21, 441,</i> quel esprit imprudent tu as ! ὡς καλός μοι ὁ πάππος, XÉN. <i>Cyr. 1, 3, 2,</i> comme mon grand-père est beau ! ὡς ἀστεῖος ὁ ἄνθρωπος, PLAT. <i>Phæd. 116</i> d, quel charmant homme ! <i>avec un verbe :</i> ὥς μοι δέχεται κακὸν ἐκ κακοῦ αἰεί, IL. <i>19, 290,</i> comme un malheur succède toujours pour moi à un malheur ! ὡς ἄρα ἐφλυαροῦμεν, XÉN. <i>Cyr. 1, 4, 11,</i> comme nous faisions des choses puériles ! <i>cf</i>. OD. <i>3, 196 ; 24, 194, etc. ; particul. pour marquer l’impatience :</i> ἀλλ' ὡς ἀπὸ τοῦ τείχους πάρεστιν ἄγγελος οὐδείς, AR. <i>Av. 1119,</i> mais comment ne vient-il du rempart aucun messager ! ;<br><b>   V</b> <i>un souhait, avec l’opt. :</i> ὡς ἔρις ἀπόλοιτο, IL. <i>18, 107,</i> puisse la discorde cesser ! ὡς ἀπόλοιτο καὶ ἄλλος, OD. <i>1, 47,</i> puisse un autre périr aussi ! ὡς ὁ τάδε πορὼν ἀπόλοιτο, SOPH. <i>El. 126,</i> périsse celui qui a fait cela ! <i>avec une négat. :</i> ὡς μὴ θάνοι, OD. <i>15, 359,</i> puisse-t-il ne pas mourir ! <i>avec l’opt. accompagné de</i> ἄν <i>ou de</i> κε, IL. <i>6, 28 ; 9, 444 ; avec un verbe marquant l’idée d’un souhait :</i> ὡς ὤφελες αὐτόθ' ὀλέσθαι, IL. <i>3, 428,</i> plût aux dieux que tu eusses péri là même ; <i>cf</i>. OD. <i>11, 548 ;</i><br><b>   VI</b> <i>une interrog. indir. : avec un adj. ou un adv. :</i> διελέγοντο πρὸς ἀλλήλους ὡς μνημονικὸς ὁ Κῦρος, XÉN. <i>Cyr. 5, 3, 17,</i> ils se disaient les uns aux autres combien Cyrus avait bonne mémoire ; θαυμάζω ὡς ἡδέως καθεύδεις, PLAT. <i>Crit. 43</i> b, j’admire comme tu dors paisiblement ; <i>cf</i>. PLAT. <i>Phæd. 89</i> a ; <i>avec un verbe :</i> ἀπαίδευτοι ὡς χρὴ συμμάχοις χρῆσθαι, XÉN. <i>Cyr. 1, 5, 7,</i> n’ayant pas appris comment il faut en user avec des alliés ; <i>particul. après un verbe marquant une idée d’incertitude :</i> μερμήριζε ὡς Ἀχιλῆα τιμήσειε, IL. <i>2, 3,</i> il méditait dans son esprit comment il honorerait Achille ; <i>après un verbe marquant une idée de crainte :</i> μὴ φοϐοῦ ὡς ἀπορήσεις, XÉN. <i>Cyr. 5, 2, 11,</i> ne crains pas de manquer de ressources ; μηκέτ' ἐκφοϐοῦ ὥς σε μητρῷον λῆμα ἀτιμάσει, SOPH. <i>El. 1426,</i> et ne crains plus que l’outrage de ta mère te déshonore ; <i>cf</i>. XÉN. <i>Cyr. 6, 2, 30 ;</i> DÉM. <i>141, 2 ; de même dans les locut. :</i> οὐκ ἔσθ' ὡς, SOPH. <i>Ant. 750,</i> il n’est pas possible que ; οὐκ ἔσθ' ὡς οὐ, SOPH. <i>Ph. 196,</i> il n’est pas possible que… ne ; <i>sur la locut</i>. οἶσθ' ὡς ποίησον, SOPH. <i>O.R. 543, v</i>. οἶδα ; <i>abs</i>. ὡς ἂν ποιήσῃς, SOPH. <i>Aj. 1369,</i> quoi que tu puisses faire, quoi que tu fasses ;<br><b>B</b> <i>conj. :</i><br><b>   I</b> que, <i>avec l’ind. :</i> ὡς εἴσ' ἀληθεῖς οἶδα, SOPH. <i>Ph. 320,</i> je sais qu’ils sont sincères ; ὡς δ' ἀληθῆ λέγω, κάλει μοι τοὺς μάρτυρας, LYS. <i>litt</i>. comme quoi je dis la vérité, appelle-moi les témoins ; οὔποτ' ἐρεῖ οὐδεὶς ὡς ἐγὼ τὴν τῶν βαρϐάρων φιλίαν εἱλόμην, XÉN. <i>An. 1, 3, 5,</i> jamais personne ne dira que j’ai préféré l’amitié des barbares ; <i>avec l’opt. conditionnel accompagné ou non de</i> ἄν : βοᾷ δὲ χοὖτος, ὡς οὐδ' ἂν Ἄρης σφ' ἐκϐάλοι, ESCHL. <i>Sept. 468,</i> et il crie lui aussi qu’Arès lui-même ne le renverserait pas ; ἔλεξε παιδὶ σῷ Ξέρξῃ τάδε, ὡς Ἕλληνες οὐ μενοῖεν, ESCHL. <i>Pers. 357,</i> il dit à ton fils Xerxès que les Grecs ne resteraient pas ; <i>avec l’opt. :</i> λέγων ὡς μεγάλα εἴη ταῦτα ἔθνη, XÉN. <i>Cyr. 1, 5, 3,</i> disant que c’étaient de grandes nations ; ἤδη καὶ ἄλλων ἤκουσα ὡς οὐ δέοι τοῦτο ποιεῖν, PLAT. <i>Phæd. 61</i> e, j’ai déjà entendu dire à d’autres qu’il ne faut pas faire cela ; διαϐάλλει τὸν Κῦρον ὡς ἐπιϐουλεύοι αὐτῷ, XÉN. <i>An. 1, 1, 3,</i> il accuse Cyrus de conspirer contre le roi ; <i>avec un part. prés. ou fut. :</i> ὡς ἐμοῦ ἰόντος ὅπῃ ἂν καὶ ὑμεῖς, οὕτω τὴν γνώμην ἔχετε, XÉN. <i>An. 1, 3, 6,</i> sachez ceci, c’est que j’irai partout où vous irez ;<br><b>   II</b> afin que, pour que, en vue de, <i>avec le sbj. après un temps principal :</i> κρῖν' ἄνδρας, ὡς φρήτρη φρήτρῃφιν ἀρήγῃ, IL. <i>2, 363,</i> choisis les hommes pour que les tribus se portent secours les unes aux autres ; ἀκούσαθ' ὡς μάθητε διὰ τέλους τὸ πᾶν, ESCHL. <i>Pr. 273,</i> écoutez pour apprendre le tout jusqu’à la fin ; <i>ellipliq</i>. ὡς τί (<i>s.-e</i>. γένηται) ; EUR. <i>Or. 796,</i> en vue de quoi ? pourquoi ? <i>avec l’opt. après un temps second. :</i> ἱκόμην ὡς μάθοιμι, SOPH. <i>El. 33</i> (lorsque) j’allai pour apprendre ; τύμϐον χεύαμεν ὥς κεν τηλεφανὴς εἴη, OD. <i>24, 83,</i> nous élevâmes un tombeau en amoncelant de la terre, de façon qu’on pût le voir de loin ; εἶχον δρέπανα ὡς διακόπτοιεν, XÉN. <i>An. 1, 8, 10,</i> ils avaient des faux pour faucher (tout ce qu’ils rencontreraient) ; <i>avec l’ind. ;</i> τί μ' οὐ λαϐὼν ἔκτεινας εὐθύς, ὡς ἔδειξα μήποτε ἐμαυτὸν ἀνθρώποισιν ἔνθεν ἦ γεγώς ; SOPH. <i>O.R. 1392,</i> pourquoi m’ayant pris ne m’as-tu pas tué tout de suite, pour m’empêcher de révéler aux hommes le secret de ma naissance ? τὰ ἐνέχυρα λαϐεῖν, ὡς μηδ' εἰ ἐϐούλετο ἐδύνατο ἐξαπατᾶν, XÉN. <i>An. 7, 6, 23,</i> prendre des gages, afin qu’il ne pût pas tromper même s’il le voulait ; <i>avec l’inf. :</i> κώθωνα ὡς ἀπὸ τοῦ ποταμοῦ ἀρύσασθαι, XÉN. <i>Cyr. 1, 2, 8,</i> une tasse pour puiser au fleuve ; <i>particul. dans les locut. :</i> ὡς ἔπος εἰπεῖν, ATT. ; <i>rar</i>. ὡς εἰπεῖν ἔπος, PLAT. <i>Leg. 967</i> c ; EL. <i>N.A. 4, 36 ; ou simpl</i>. ὡς εἰπεῖν, HDT. <i>6, 95 ; 7, 24,</i> pour ainsi dire ; ὡς λόγῳ εἰπεῖν, HDT. <i>2, 53, m. sign. ;</i> ὡς συντόμως εἰπεῖν, XÉN. <i>Œc. 12, 19 ;</i> ὡς συνελόντι εἰπεῖν, XÉN. <i>Mem. 3, 8, 10,</i> pour le dire en peu de mots, bref ; ὡς ἐν πλέονι λόγῳ δηλῶσαι, HDT. <i>2, 25,</i> pour le montrer plus longuement, <i>etc. ;</i><br><b>   III</b> de telle sorte que, <i>avec l’inf. :</i> εὖρος ὡς δύο τριήρεις πλέειν ὁμοῦ, HDT. <i>7, 24,</i> d’une largeur telle que deux trirèmes pussent y naviguer de front ; ἐνετύγχανον τάφροις πλήρεσιν ὕδατος ὡς μὴ δύνασθαι διαϐαίνειν, XÉN. <i>An. 2, 3, 10,</i> ils rencontraient des fossés pleins d’eau, de telle sorte qu’ils ne pouvaient les traverser (sans ponts) ; <i>avec l’inf. et le nom. :</i> οὕτως ὡπλισμένοι ὡς ὅτι προσωτάτω ταχθέντες μάχεσθαι, XÉN. <i>Cyr. 2, 1, 11,</i> armés de façon à combattre en ligne le plus loin possible ; avec <i>ind. :</i> οὕτως ἐμοὶ ἐϐοήθησας ὡς νῦν σέσωσμαι, XÉN. <i>Cyr. 5, 4, 6,</i> tu m’as secouru de telle sorte, que me voilà sauvé ; νομίζω οὕτως ἔχειν, ὡς ἀποστήσονται αὐτοῦ αἱ πόλεις, XÉN. <i>Hell. 6, 1, 4,</i> les choses sont telles, que les villes, je pense, se détacheront de lui ; <i>cf</i>. ESCHL. <i>Pr. 155, Pers. 72 ;</i> XÉN. <i>Cyr. 3, 1, 38 ; avec l’impér. :</i> ὡς κυκάτω πάντα, AR. <i>Pax 320,</i> ainsi donc qu’elle (la guerre) mette tout sens dessus dessous. <i>Lorsque l’antécéd</i>. οὕτως (<i>v. les ex. préc</i>.), τοῖόσδε <i>ou autre semblable se trouve exprimé dans la 1<sup>re</sup> prop.,</i> ὡς <i>est qqf. s.-e. dans la 2<sup>e</sup>, particul. chez Hérodote :</i> οὕτω ἰσχυραὶ (ὡς) μόγις ἂν λίθῳ παίσας διαρρήξειας, HDT. <i>3, 12,</i> tellement dures, qu’à peine on pourrait les briser à coups de pierres ; ῥώμη σώματος τοιήδε (ὡς) ἀεθλοφόροι ἤσαν ἀμφότεροι, HDT. <i>1, 31,</i> une telle force corporelle, que tous deux remportaient le prix de la lutte ;<br><b>   IV</b> lorsque, après que, <i>et avec</i> εὐθύς <i>ou</i> τάχιστα, dès que, <i>avec l’ind. :</i> ὡς ἴδον Ἥφαιστον, IL. <i>1, 600,</i> lorsqu’ils virent Hèphæstos ; ὡς δὲ εἶδεν ἔλαφον, XÉN. <i>Cyr. 1, 4, 8,</i> lorsqu’il eut vu une biche ; εὐθὺς ὡς ἤκουσεν, ESCHL. <i>Pers. 353,</i> dès qu’il eut appris ; ὡς δὲ τάχιστα ἀφίκετο, εὐθύς, <i>etc</i>. XÉN. <i>Cyr. 1, 3, 2,</i> dès qu’il fut arrivé, aussitôt, <i>etc. ;</i> ὡς εἶδον αὐτούς, εὐθὺς ἔφυγον, XÉN. <i>Cyr. 3, 1, 4,</i> lorsqu’ils les virent, ils prirent la fuite ; <i>avec l’inf. dans le disc. indir. :</i> ὡς ἄρα μιν προσστῆναι τοῦτο, ἐς τρὶς ὀνομάσαι Σόλωνα, HDT. <i>1, 86</i> (on raconte que), aussitôt que ce souvenir lui fut revenu, il prononça trois fois le nom de Solon ; <i>avec le subj. ou l’opt. pour marquer l’idée de répétition :</i> toutes les fois que, chaque fois que : ὡς δὲ εἰς τὴν Μιλησίην ἀπίκοιτο, HDT. <i>1, 17,</i> toutes les fois qu’il arrivait en Milésie ; τῶν δὲ ὡς ἕκαστός οἱ μιχθῇ, διδοῖ δῶρον, HDT. <i>4, 172,</i> à mesure que chacun d’eux s’est uni à la femme, il fait un présent ;<br><b>   V</b> parce que, puisque, car, <i>avec l’ind. :</i> τί ποτε λέγεις, ὦ τέκνον ; ὡς οὐ μανθάνω, SOPH. <i>Ph. 914,</i> que veux-tu dire, enfin, mon enfant ? car je ne comprends pas ; μὴ καὶ λάθῃ με προσπεσών, ὡς μᾶλλον ἂν ἕλοιτό μ' ἢ τοὺς πάντας Ἀργείους λαϐεῖν, SOPH. <i>Ph. 46,</i> de peur qu’il ne tombe sur moi à l’improviste, car il aimerait mieux s’emparer de moi que de tous les Grecs ; φυλάξασθαι δεῖ τὸ ἐφ' ἁρπαγὴν τραπέσθαι, ὡς ὁ τοῦτο ποιῶν οὐκέτ' ἀνήρ ἐστιν, XÉN. <i>Cyr. 4, 2, 25,</i> il faut se garder de se laisser entraîner au rapt, puisque (car) celui qui fait cela n’est plus un homme.<br><span><b><span class=\"arrow\"></span></b> <i>Dans Hom. la finale brève du mot qui précède</i> ὡς <i>est allongée :</i> ὄρνιθες ὥς, πέλεκυς ὥς, θεὸς ὥς, ὡς <i>étant pour</i> *ϳώς, <i>comme</i> ὅς <i>pour</i> *ϳός.<br><span><b>Étym</b>. ὡς « comme » : <i>indo-europ</i>. *Hio-, <i>anc. instrum.-abl. du pron. rel</i>. ὅς, <i>cf. sscr</i>. yā́t ; ὥς <i>démonstr</i>. « ainsi » : <i>instrum. de</i> *so-, *to-, <i>pron. démonstr., v</i>. ὁ.</span></span><br><br>\n➃ <b>ὥς</b>, <i>adv</i>., ainsi, de cette façon :<br><b>      1</b> <i>abs</i>. HOM. ATT. (ESCHL. <i>Ag. 930 ;</i> THC. <i>3, 37, etc</i>.) ; ὣς φάτο, HOM. il parla ainsi ; ὣς εἰπών, HOM. ayant parlé ainsi ; <i>en prose seul</i>. HDT. <i>3, 13 ; 6, 76, etc. ;</i> PLAT. <i>Prot. 338</i> b ; ARSTT. <i>Phys. 5, 6 ;</i> ARR. <i>An. 4, 28, 1 ; et dans les locut</i>. καὶ ὥς, IL. <i>1, 116, etc. ;</i> ATT. même ainsi, <i>d’où</i> néanmoins, toutefois ; οὐδ' ὥς <i>ou</i> μηδ' ὥς, IL. <i>7, 263, etc. ;</i> OD. <i>1, 6, etc. ;</i> THC. <i>1, 44 ;</i> XÉN. <i>Cyr. 3, 3, 11, etc</i>. pas même ainsi ; οὐδέ κεν ὥς, IL. <i>9, 386, m. sign. ;</i><br><b>      2</b> pour marquer une comparaison : ὡς… ὥς, ATT. comme…, ainsi ; de même que…, de même ; ὥστε…, ὥς, HH. <i>Cer. 174, etc</i>. et comme…, de même, <i>etc. ;</i> ὥσπερ…, ὣς δὲ καί, PLAT. <i>Prot. 326</i> d, comme… de même aussi, <i>etc. ;</i><br><b>      3</b> <i>pour marquer une idée de simultanéité :</i> ὡς…, ὥς, ATT. comme…, en même temps ; au moment où…, à ce moment même ;<br><b>      4</b> <i>pour marquer une conséquence ;</i> par suite, à cause de cela, OD. <i>2, 137 ; 9, 306 ; 24, 93 ;</i><br><b>      5</b> <i>pour annoncer une preuve, un témoignage, un exemple :</i> ainsi par exemple, OD. <i>5, 121, 125 ;</i> HH. <i>Ven. 210</i>.<br><span><b>Étym</b>. <i>adv. de l’anc. pron. démonstr</i>. ὅς.</span><br><br>\n➄ <b>ὧς</b> <i>ou</i> <b>ὡς</b>, <i>adv. de lieu dor. c</i>. οὗ, où, THCR. <i>Idyl. 1, 13 ; 5, 101, etc</i>.<br><br>\n➅ <b>ὡς</b>, <i>prép. avec l’acc</i>. vers, <i>primit. et en poésie avec un nom de pers. :</i> αἰεὶ τὸν ὁμοῖον ἄγει θεὸς ὡς τὸν ὁμοῖον, OD. <i>17, 218 (seul ex. de de cet emploi dans Homère</i>) toujours un dieu pousse le semblable vers son semblable ; ὡς ὑμᾶς, SOPH. <i>Tr. 530,</i> vers vous ; ὡς τὸν Δία, AR. <i>Pax 104,</i> vers Zeus ; ὡς τὴν θυγατέρα, HDT. <i>2, 121,</i> vers sa fille ; ὡς Ἆγιν ἐπρεσϐεύσαντο, THC. <i>8, 5,</i> ils envoyèrent des députés vers Agis, <i>etc. ; si le verbe de mouv. se trouve avoir pour régimes à la fois un n. de pers. et un n. de lieu, le premier se construit avec</i> ὡς, <i>le second avec</i> εἰς : ναῦς ἐς τὸν Ἑλλήσποντον ὡς Φαρνάϐαζον πέμπειν, THC. <i>8, 81,</i> envoyer des vaisseaux dans l’Hellespont contre Pharnabaze ; ἀφίκετο ὡς Περδίκκαν καὶ ἐς τὴν Χαλκιδικήν, THC. <i>4, 79,</i> il alla vers Perdiccas et dans la Chalcidique ; <i>cf</i>. THC. <i>8, 39, etc. ; postér. et en prose avec un n. de lieu :</i> ὡς τὸν Μίλητον, THC. <i>8, 36,</i> vers Milet ; ὡς Ἄϐυδον, THC. <i>8, 102,</i> vers Abydos.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. cinq ex. seul. devant des n. de pers. :</i> ὡς βασιλέα, ὡς αὐτὸν (<i>envir. 370 av. J.C</i>.) ; <i>v. Meisterh. p. 183, 54</i>.<br><span><b>Étym</b>. <i>obscure</i>.</span></span><br><br>\n➆ <b>ὥς</b>, <i>pour</i> ὡς, <i>quand il est placé après le mot auquel il se rapporte</i>.<br><span><b>Étym</b>. <i>v</i>. ὡς.</span><br><br>\n➇ <b>ὡς</b>, <i>v</i>. ὧς.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ως - ὡς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n486 fois dans 427 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (35)</li>\n<li>Marc (23)</li>\n<li>Luc (51)</li>\n<li>Jean (25)</li>\n<li>Actes (61)</li>\n<li>Romains (21)</li>\n<li>1 Corinthiens (41)</li>\n<li>2 Corinthiens (29)</li>\n<li>Galates (9)</li>\n<li>Ephésiens (14)</li>\n<li>Philippiens (7)</li>\n<li>Colossiens (7)</li>\n<li>1 Thessaloniciens (9)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (5)</li>\n<li>Tite (2)</li>\n<li>Philémon (4)</li>\n<li>Hébreux (20)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (29)</li>\n<li>2 Pierre (10)</li>\n<li>1 Jean (2)</li>\n<li>2 Jean (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (65)</li>\n</ul>\n</td></tr>\n</table>","G5614":"<h1>hosanna</h1>\n<p>Strong n° 5614 <i>Prononciation [ho-san-nah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hosanna = « sauve, maintenant ! »\n<ol>\n<li>hosanna</li>\n<li>être propice, viens donc à notre aide</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὡσαννά</b>, hosanna, cri de joie, de triomphe, SPT. <i>Ps. 118, 25</i>.<br><span><b>Étym</b>. <i>hébr</i>. hoschiah na, ‎הוֹשַׁענָא.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωσαννα</font> &lt; הושע־נא - <font face=\"Georgia\">ὡσαννά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Interjection</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5615":"<h1>hosautos</h1>\n<p>Strong n° 5615 <i>Prononciation [ho-sow'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de la même manière, de même</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὡσ·αύτως</b>, <i>adv</i>., de même, ainsi, également, de la même manière, <i>chez Hom. touj. séparé par</i> δέ : ὣς δ' αὔτως (<i>ou</i> αὕτως) IL. <i>3, 339 ; 7, 430 ; 9, 195 ; 10, 25 ;</i> OD. <i>6, 166 ; 9, 31 ; 20, 238, etc. ; de même qqf. en prose,</i> HDT. <i>1, 215 ; 2, 67, etc. ;</i> XÉN. <i>Hell. 2, 2, 9 ; Cyr. 2, 1, 22 ; etc. ;</i> PLAT. <i>Phæd. 102</i> e, <i>etc. ; mais d’ordin. non séparé,</i> XÉN. <i>Cyr. 1, 1, 4 ; 1, 6, 3, etc. ;</i> PLAT. <i>Phil. 56</i> b ; PLUT. <i>M. 1116</i> c, <i>etc. ;</i> SPT. <i>Deut. 12, 22 ;</i> NT. <i>Luc. 13, 3 ; après le verbe,</i> XÉN. <i>An. 3, 2, 23 ;</i> SPT. <i>Judith 8, 8 ;</i> NT. <i>Matth. 20, 5 ; avec omiss. du verbe,</i> XÉN. <i>An. 4, 7, 13 ; 5, 6, 9, etc. ;</i> PLAT. <i>Charm. 167</i> c, <i>Gorg. 474</i> e, <i>etc. ; en corrélat. avec</i> ὥσπερ, de même que…, de même, XÉN. <i>Vect. 4, 6, etc. ; avec</i> ὡς, <i>placé après,</i> SPT. <i>Deut. 15, 22 ; ou</i> οἷον, PLAT. <i>Phæd. 72</i> c ; <i>pléonastiq. avec</i> οὕτως, XÉN. <i>Cyr. 1, 1, 4 ; 1, 6, 3 ;</i> PLAT. <i>Phæd. 98</i> a, <i>etc. ; avec</i> κατὰ ταὐτά, PLAT. <i>Phæd. 78</i> d, <i>etc. ; Soph. 248</i> b, <i>etc. ;</i> κατὰ ταὐτό, PLUT. <i>M. 1001</i> d ; <i>avec</i> ταὐτόν, PLAT. <i>Leg. 868</i> d, <i>etc. ; p. opp. à</i> ὡς ἑτέρως, ARSTT. <i>Soph. el. 7 ; avec le dat</i>. HDT. <i>2, 67 ;</i> PLAT. <i>Theæt. 156</i> c, <i>etc. ; de même avec</i> καί, HDT. <i>7, 86 ; avec le gén., pour marquer une idée de degré,</i> PLAT. <i>Rsp. 576</i> d.<br><span><b>Étym</b>. ὡς, αὔτως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωσαυτως - ὡσαύτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 17 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Timothée (4)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G5616":"<h1>hosei</h1>\n<p>Strong n° 5616 <i>Prononciation [ho-si']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>comme</li>\n<li>à peu près, vers, environ, presque\n<ol type=\"a\">\n<li>devant des nombres</li>\n<li>devant une mesure de temps</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὡσ·εί</b>, <i>conj. :</i><br><b>      1</b> comme si, comme lorsque, <i>avec l’opt</i>. IL. <i>2, 780 ; 11, 389, etc. ;</i> SOPH. <i>Ant. 649 ;</i> ὡσεί τε <i>avec le sbj</i>. IL. <i>9, 481, ou l’ind</i>. IL. <i>13, 492 ;</i> PD. <i>O. 7, 1 ;</i><br><b>      2</b> comme, de même que, <i>avec un subst</i>. IL. <i>16, 59 ;</i> OD. <i>7, 36 ;</i> HÉS. <i>Sc. 390 ;</i> ESCHL. <i>Suppl. 782 ;</i> SOPH. <i>Ant. 653, etc. ; avec un part</i>. IL. <i>5, 374 ;</i> HÉS. <i>Sc. 194, 198 ; de même</i> ὡσεί τε, <i>abs</i>. IL. <i>11, 474 ;</i> OD. <i>9, 314 ; 14, 254 ;</i> ὡσεί περ <i>avec un part</i>. HÉS. <i>Sc. 189 ;</i> THCR. <i>Idyl. 25, 163 ;</i> ὡσεί πέρ τε, <i>abs</i>. HH. <i>Cer. 215 ;</i><br><b>      3</b> comme, à peu près, environ, XÉN. <i>Hell. 1, 2, 9 ; 2, 4, 25</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωσει - ὡσεί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n34 fois dans 34 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (10)</li>\n<li>Jean (5)</li>\n<li>Actes (8)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5617":"<h1>Hosee</h1>\n<p>Strong n° 5617 <i>Prononciation [ho-say-eh']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Osée (Hosea) = « salut »\n<ol><li>le prophète Hébreu bien connu, fils de Beéri et contemporain d'Esaïe <a class=\"ref\" data-r=\"HOS1.1\">Osée 1.1</a></li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ωσηε</font> &lt; הושע - <font face=\"Georgia\">Ὡσηέ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5618":"<h1>hosper</h1>\n<p>Strong n° 5618 <i>Prononciation [hoce'-per]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>juste comme, de même que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὥσ·περ</b>, <i>adv. et conj. :</i><br><b>A</b> <i>adv</i>., comme, de même que : <i>marque :</i><br><b>   I</b> <i>une comparaison :</i><br><b>      1</b> comme, de même que : <i>avec un même verbe exprimé dans les deux prop. :</i> ζῆν ὥσπερ ἤδη ζῇς SOPH. <i>Ph. 1396,</i> vivre comme tu vis déjà ; ἐσῴζετ' ἂν ὥσπερ οὐχὶ σῴζεται, SOPH. <i>Ph. 994,</i> il aurait été sauvé justement comme il ne l’est pas ; <i>d’ord. avec omiss. du verbe dans la 2<sup>e</sup> prop. :</i> τοῖς ἠτυχηκόσιν ὥσπερ ἐγώ, DÉM. <i>1101, 6,</i> à ceux qui sont malheureux comme moi, IL. <i>4, 264 ; 14, 50 ;</i> OD. <i>7, 206 ;</i> AR. <i>Ran. 303, etc. ; avec un corrélat. exprimé soit avant :</i> τηλίκου ὥσπερ ἐγών, IL. <i>24, 487,</i> du même âge que moi ; τοιοῦτος ὥσπερ, PLAT. <i>Prot. 327</i> d, tel que, <i>etc. ; particul. après</i> ὁ αὐτός, PLAT. <i>Phæd. 86</i> a, <i>etc. ; après</i> ἴσος, OD. <i>20, 281 ; après</i> ὅμοιος, ESCHL. <i>Ag. 1311 ; après</i> ὁμοίως, THC. <i>4, 34 ; soit après :</i> ὥσπερ…, ὧδε, SOPH. <i>O.R. 276,</i> de même que…, de même ; ὥσπερ καί…, οὕτω καί, XÉN. <i>Cyr. 7, 15, 75, etc.,</i> de même que aussi…, de même aussi, <i>etc. ; cf</i>. PLAT. <i>Rsp. 354</i> b ; SOPH. <i>Tr. 475, etc. ; renforcé par une particule :</i> ὥσπερ γε, AR. <i>Nub. 673,</i> justement comme, exactement comme ; ὥσπερ καί, THC. <i>1, 142, etc.,</i> comme aussi, <i>etc. ; dans Hom. qqf. séparé par un ou deux mots :</i> ὡς ἔσεταί περ, OD. <i>19, 312,</i> comme il sera ; ὡς σύ περ αὐτή, OD. <i>19, 385,</i> comme toi-même ; ὡς σύ περ ὧδε, IL. <i>21, 398,</i> ainsi que toi ; ὡς καὶ ἐγώ περ, IL. <i>6, 477,</i> comme moi-même ; ὥσπερ ἂν εἴ τις ἀσπάζοιτο, XÉN. <i>Cyr. 1, 3, 2,</i> c comme l’aurait embrassé qqn (qui l’aurait connu depuis longtemps), <i>litt</i>. comme qqn l’aurait embrassé, si, <i>etc. ; cf</i>. PLAT. <i>Gorg. 479</i> a, <i>Prot. 311</i> b, <i>etc. ; ou avec l’ind. ao. et impf</i>. ATT. ;<br><b>      2</b> que, <i>après un compar</i>. IL. <i>4, 263 ;</i> XÉN. <i>Hell. 3, 3, 16 ;</i><br><b>   II</b> <i>un état :</i><br><b>      1</b> dans l’état où, de la façon que : ὥσπερ λέγω, PLAT. <i>Prot. 316</i> e, comme je dis ; <i>avec un gén. :</i> ὥσπερ ἔχει δόξης, PLAT. <i>Rsp. 612</i> d, selon son opinion ; <i>avec</i> ἄν : ὥσπερ ἄν τις λέγοι, PLAT. <i>Phæd. 87</i> b, comme on pourrait dire ;<br><b>      2</b> en tant que, parce que, THC. <i>7, 18, 80 ; 8, 22, etc. ;</i> XÉN. <i>Ap. 33 ;</i> SOPH. <i>Aj. 1391, etc. ; avec l’inf</i>. ὥσπερ εἰπεῖν, LUC. <i>V.H. 9,</i> comme pour dire ;<br><b>   III</b> ὥσπερ ἄν <i>avec le subj. pour exprimer une idée de temps :</i><br><b>      1</b> tant que : ὥσπερ ἂν ζῶ, SOPH. <i>O.C. 1361,</i> aussi longtemps que je vivrai (<i>sel. d’autres,</i> de qqe façon que je vive) ;<br><b>      2</b> aussitôt, aussitôt que, AR. <i>Pax 14 ;</i><br><b>   IV</b> <i>une explication, un témoignage, une preuve,</i> comme, par exemple : ὅταν χορὸς γίγνηται, ὥσπερ ὁ εἰς Δῆλον πεμπόμενος, XÉN. <i>Mem. 3, 3, 12,</i> lorsqu’on forme un chœur, comme par exemple celui qu’on envoie à Dèlos ; <i>cf</i>. IL. <i>14, 50 ;</i> SOPH. <i>O.C. 780 ;</i> PLAT. <i>Gorg. 451</i> a, <i>etc. ;</i><br><b>   V</b> en quelque façon, à peu près : ὥσπερ ἀκονιτί, THC. <i>4, 73,</i> pour ainsi dire sans effort ; <i>cf</i>. XÉN. <i>An. 3, 1, 14 ;</i> PLAT. <i>Crat. 384</i> c, <i>Phæd. 88</i> e, <i>Prot. 346</i> a, <i>etc. ;</i><br><b>   VI</b> comme si, <i>avec un part. :</i> ὥσπερ ἐγγελῶσα τοῖς ποιουμένοις, SOPH. <i>El. 277,</i> comme s’applaudissant de ce qu’elle avait fait, <i>particul. avec un part. abs. au gén. :</i> ὥσπερ ἐντεταμένου τοῦ σώματος, PLAT. <i>Phæd. 86</i> b, comme si le corps était tendu ; ὥσπερ ἐξόν, XÉN. <i>An. 3, 1, 14,</i> comme si cela était en notre pouvoir ; ὥσπερ τοῦτο ἐπιτεταγμένον αὐτοῖς, XÉN. <i>Conv. 1, 4,</i> comme si cela leur avait été ordonné ;<br><b>B</b> <i>conj</i>. afin que, pour que : φάλαγγα ἔχοντες, ὥσπερ ἰσχυρότεροι ἂν εἴητε, XÉN. <i>Cyr. 7, 1, 11,</i> ayant une troupe rangée, pour que vous soyez plus forts.<br><span><b>Étym</b>. ὡς, περ.</span><br><br>\n➁ <b>ὤσ·περ</b>, <i>barbarisme d’un Scythe pour</i> ὥσπερ, AR. <i>Th. 1185, 1192</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωσπερ - ὥσπερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 42 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5619":"<h1>hosperei</h1>\n<p>Strong n° 5619 <i>Prononciation [hoce-per-i']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>comme, comme il était</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὡσπερ·εί</b>, <i>conj. :</i> comme si, <i>avec l’ind</i>. ESCHL. <i>Ag. 1201 ; avec l’opt</i>. SOPH. <i>O.C. 776 ; avec l’inf</i>. ὡσπερεὶ φάναι, LGN <i>32, 3,</i> pour ainsi dire ; <i>avec un subst</i>. comme si c’était, AR. <i>Lys. 115 ;</i> PLAT. <i>Crat. 422</i> a ; <i>de même dev. un part</i>. AR. <i>Eccl. 537</i>.<br><span><b>Étym</b>. ὥσπερ, εἰ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωσπερει - ὡσπερεί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5620":"<h1>hoste</h1>\n<p>Strong n° 5620 <i>Prononciation [hoce'-teh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>c'est ainsi que</li>\n<li>ainsi, alors, donc, c'est pourquoi, pour quelle raison</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ὥσ·τε</b>, <i>adv. et conj. :</i><br><b>   I</b> <i>adv. :</i><br><b>      1</b> comme (<i>seul. en poésie et en prose ion</i>.) IL. <i>2, 289 ; 9, 14 ; 10, 154, etc. ;</i> PD. <i>O. 11, 86 ; P. 4, 64 ; 10, 54 ; N. 7, 71 ;</i> SOPH. <i>Ant. 1033, 1084 ; Aj. 300 ; O.C. 344 ;</i> HDT. <i>1, 8 ; 6, 94 ;</i> ὥστε μύρμηκες, ESCHL. <i>Pr. 450,</i> comme des fourmis ; <i>qqf. séparé :</i> ὥς τίς τε λέων, IL. <i>17, 133,</i> comme un lion ; <i>qqf. après le mot auquel il se rapporte :</i> κόρακες ὥστε, ESCHL. <i>Suppl. 751,</i> comme des corbeaux, <i>joint à</i> περ : ὥστε περ, IL. <i>18, 518,</i> de même que ;<br><b>      2</b> comme, en qualité de (<i>seul. dans Hom. et dans la prose ion</i>.) ὥστε θεός, IL. <i>3, 381,</i> en qualité de déesse ; <i>cf</i>. IL. <i>2, 289 ; 9, 14, etc. ;</i> HDT. <i>5, 83, 101 ; 6, 94 ; 8, 118, etc. ; avec un part</i>. attendu que, vu que : ὥστε φυλασσομένων τῶν ὁδῶν, HDT. <i>5, 35,</i> attendu que les routes étaient gardées ; <i>elliptiq</i>. ὥστε περὶ ψυχῆς, OD. <i>9, 423,</i> attendu qu’il s’agissait de la vie ;<br><b>   II</b> <i>conj. :</i><br><b>      1</b> de telle sorte que, <i>avec l’ind. :</i> καὶ εἰς μὲν τὴν ὑστεραίαν οὐχ ἧκεν, ὥσθ' οἱ Ἕλληνες ἐφρόντιζον, XÉN. <i>An. 2, 3, 25,</i> et le lendemain il ne revint pas, de sorte que les Grecs étaient soucieux ; <i>avec un temps secondaire de l’ind. (impf. ou ao.) accompagné de</i> ἄν <i>pour marquer l’idée d’une conséquence éventuelle dépendant d’un fait qui aurait pu se produire, mais qui ne s’est pas produit :</i> ὥστ' εἰ φρονῶν ἔπρασσον, οὐδ' ἂν ὦδ' ἐγιγνόμην κακός, SOPH. <i>O.C. 271,</i> de telle sorte que si j’avais agi avec réflexion, je ne serais pas devenu méchant ; ὥστε οὐκ ἂν ἔλαθεν αὐτόθεν ὁρμώμενος, THC. <i>5, 6,</i> de telle sorte que son départ n’aurait pas échappé à l’attention ; <i>avec l’inf. ao</i>. ὥστε ἀποπλησθῆναι τὸν χρησμόν, HDT. <i>8, 96,</i> de sorte que l’oracle fut accompli ; <i>avec l’opt. conditionn. :</i> ὥστε ὁ βίος ἀϐίωτος γίγνοιτ' ἄν, PLAT. <i>Pol. 299</i> e, de sorte que la vie deviendrait intolérable : <i>en ce sens sans prop. antér. exprimée, de telle sorte que ὥστε se rattache à ce qui précède pour marquer une sorte de conclusion :</i> ὥστ' ὄλωλα καὶ σὲ προσδιαφθερῶ, SOPH. <i>Ph. 75,</i> de sorte que je suis perdu, et en outre je te perdrai avec moi ; <i>avec un impér. :</i> ὥστε μὴ λίαν στένε, SOPH. <i>El. 1172,</i> ainsi ne te lamente pas trop ; ὥστε θάρρει, XÉN. <i>Cyr. 1, 3, 18,</i> ainsi courage ! <i>p. suite, au commenc. d’une phrase,</i> de sorte que, c’est pourquoi, ATT. ;<br><b>      2</b> à ce point que, <i>d’ord. avec un antécéd</i>. οὕτω, τηλίκος, <i>etc. ; avec l’ind. :</i> οὐχ οὕτω φρενοϐλαϐέες ἦσαν ὥστε ἐϐούλοντο, HDT. <i>2, 120,</i> ils n’auraient pas été insensés au point de vouloir, <i>etc. ;</i> οὕτως ἥσθη τῇ θήρᾳ ὥστε ἀεὶ συνεξῄει τῷ Κύρῳ, XÉN. <i>Cyr. 1, 4, 15,</i> il prit tant de plaisir à la chasse qu’il sortait toujours avec Cyrus ; <i>cf</i>. HDT. <i>3, 12 ;</i> SOPH. <i>O.R. 533, O.C. 82 ;</i> XÉN. <i>An. 1, 9, 28, Mem. 2, 2, 3 ; avec l’inf. :</i> οὐ τηλίκος εἰμὶ ὥστε σημάντορι πάντα πιθέσθαι, OD. <i>17, 21,</i> je ne suis pas d’âge à obéir en tout à un maître ; <i>avec l’inf. sans</i> ἄν, <i>si la prop. annoncée par ὥστε exprime un fait réel ; avec ἄν, si elle marque l’idée d’une chose qui pourrait être, mais qui n’est pas :</i> ἤδη γὰρ ὑπέφαινέ τι ἡμέρας, ὥστε καταφανῆ αὐτὸν γενέσθαι, PLAT. <i>Prot. 312</i> a, en effet, le jour commençait à poindre assez pour qu’on pût commencer à le voir ; τὰ ἐντὸς οὕτως ἐκάετο ὥστε μήτε ἄλλο τι ἢ γυμνοὶ ἀνέχεσθαι, ἥδιστά τε ἂν ἐς ὕδωρ ψυχρὸν σφᾶς αὐτοὺς ῥίπτειν, THC. <i>2, 49,</i> l’intérieur du corps était brûlé par le feu de la maladie au point qu’ils ne pouvaient supporter d’être autrement que nus, et que c’eût été pour eux une jouissance extrême de se jeter dans l’eau froide ; οἱ θεοὶ ἐν τοῖς ἱεροῖς ἐσήμηναν ὥστε καὶ ἰδιώτην ἂν γνῶναι, XÉN. <i>An. 5, 10, 31,</i> les dieux le firent entendre assez clairement pour que même un profane pût le comprendre ; <i>cf</i>. HÉS. <i>O. 44 ;</i><br><b>      3</b> pour que, <i>avec l’inf. :</i> εἰ δέ τοι αὐτῷ θυμὸς ἐπέσσυται ὥστε νέεσθαι, ἔρχεο, IL. <i>9, 42,</i> si ton cœur te pousse à retourner, va ; <i>surt. après un compar. :</i> μέζω κακὰ ἢ ὥστε ἀνακλαίειν, HDT. <i>3, 14, 159</i> maux trop grands pour qu’on les déplore en plaintes bruyantes ; μεῖζον ἢ ὥστε φέρειν δύνασθαι κακόν, XÉN. <i>Mem. 3, 5, 17,</i> malheur trop grand pour qu’on puisse le supporter ; <i>en ce sens ὥστε est qqf. s.-e. :</i> νόσημα μεῖζον ἢ φέρειν, SOPH. <i>O.R. 1293,</i> mal trop grave pour qu’on le supporte ; <i>après un positif :</i> ψυχρὸν ὥστε λούσασθαι, XÉN. <i>Mem. 3, 13, 3,</i> eau trop froide pour s’y baigner ; ἡμεῖς γὰρ ἔτι νέοι ὥστε τοσοῦτον πρᾶγμα διελέσθαι, PLAT. <i>Prot. 314</i> b, car nous sommes bien jeunes pour décider une si grande affaire ; <i>cf</i>. EUR. <i>Andr. 80 ; en ce sens ὥστε est qqf s.-e. :</i> ὀλίγους εἶναι στρατιῇ τῇ Μήδων συμϐάλλειν, HDT. <i>6, 109,</i> trop peu nombreux pour en venir aux mains avec l’armée des Mèdes ; <i>cf</i>. THC. <i>1, 50 ; 2, 61 ;</i> PLAT. <i>Menex. 239</i> b ; <i>p. suite,</i> à la condition que : ἐκήρυξάν τε, εἰ βούλοιντο, τὰ ὅπλα παραδοῦναι Ἀθηναίοις ὥστε βουλεῦσαι ὅτι ἂν ἐκείνοις δοκῇ, THC. <i>4, 37,</i> ils firent demander par un héraut s’ils voulaient livrer leurs armes aux Athéniens, en laissant ces derniers prononcer sur leur sort comme ils l’entendraient ; εἰδὼς ἃ ἐπαγγέλλοιντο, ὥστε ἐκπλεῖν, XÉN. <i>An. 5, 6, 26,</i> sachant ce qu’ils proposeraient, à condition de s’éloigner par mer.<br><span><b>Étym</b>. ὡς, τε.</span><br><br>\n➁ <b>ὥστε</b>, <i>dor. c</i>. οὕστε, <i>acc. pl. de</i> ὅστε.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωστε - ὥστε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n84 fois dans 83 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (13)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (8)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (14)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (5)</li>\n<li>Philippiens (3)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5621":"<h1>otion</h1>\n<p>Strong n° 5621 <i>Prononciation [o-tee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'oreille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠτίον, ου (τὸ) :<br>      1</b> petite oreille, ANTH. <i>11, 81 ;</i> SPT. <i>1Reg. 9, 15, etc. ;</i> NT. <i>Matth. 26, 51 ;</i><br><b>      2</b> petite anse, HÉRON (MATH. <i>p. 163</i>).<br><span><b>Étym</b>. <i>dim. de</i> οὖς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωτιον - ὠτίον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G5622":"<h1>opheleia</h1>\n<p>Strong n° 5622 <i>Prononciation [o-fel'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>utilité, avantage, profit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠφέλεια</b> <i>ou</i> <b>ὠφελία, ας (ἡ) :<br>   I</b> secours, aide, assistance, <i>en gén</i>. ὠφελίαν ὠφελεῖν, PLAT. <i>Euthyd. 275</i> e, rendre service ; ὠφέλειαν παρέχειν, fournir assistance à qqn ; ὠφέλειάν τινι φέρειν, EUR. <i>fr. 79,</i> porter secours à qqn ; ὠφελίαν προσλαμϐάνειν, THC. <i>2, 17,</i> recevoir assistance ; ὠφελίας εὑρίσκεσθαι ἀπό τινος, THC. <i>1, 31,</i> trouver du secours en qqn ; ὠφελίας τυγχάνειν, THC. <i>6, 17,</i> obtenir du secours ; <i>particul</i>. secours de guerre, THC. <i>1, 26, 39, etc. ; ou</i> secours d’un médecin, <i>joint à</i> ἰατρική, PLAT. <i>Lys. 217</i> a ;<br><b>   II</b> utilité, avantage :<br><b>      1</b> <i>au sens abstrait, en gén. p. opp. à</i> βλαϐή, XÉN. <i>Cyr. 6, 2, 13, etc. ; à</i> ζημία, XÉN. <i>Mem. 2, 3, 6, etc. ;</i> ἀπ' οὗ ἔμελλε οὐδεμία ὠφελίη ἔσεσθαι, HDT. <i>5, 98,</i> d’où il ne devait résulter aucun avantage ; ἐπ' ὠφελείᾳ ἐστί <i>ou</i> γίγνεταί τι, XÉN. <i>Mem. 1, 4, 4,</i> qqe ch. est <i>ou</i> se produit à l’avantage de, <i>etc. ;</i> τίς ἂν εἴη ἡμῖν ὠφέλεια εἰδόσιν αὐτό ; PLAT. <i>Charm. 167</i> b, quel avantage aurions-nous à savoir cela ? τὴν κοινὴν ὠφελίαν φυλάξαι, THC. <i>6, 80,</i> veiller à l’intérêt commun ; <i>avec le gén. de la pers. ou de la chose dont on tire utilité :</i> ἡ ὠφελίη ἡ τῶν τειχέων, HDT. <i>7, 139,</i> l’utilité des remparts ; <i>ou de la pers. ou de la chose à qui l’on rend service ;</i> ἐπ' ὠφελείᾳ τινός, THC. <i>1, 3 ; 5, 73, etc. ;</i> XÉN. <i>Mem. 1, 4, 4, etc. ;</i> PLAT. <i>Rsp. 334</i> c, <i>etc. à l’avantage ou dans l’intérêt de qqn ;</i> ὠφελείας ἕνεκα, PLAT. <i>Rsp. 398</i> b ; τῆς ὠφελείας χάριν, POL. <i>3, 82, 8, m. sign. ;</i><br><b>      2</b> <i>au sens concret,</i> SEXT. <i>p. 160, 28, etc. ; d’ord. au plur</i>. les avantages, les profits, ISOCR. <i>43</i> e, <i>46</i> c ; <i>p. opp. à</i> βλαϐαί, PLAT. <i>Rsp. 332</i> d ; <i>particul</i>. les services rendus, DÉM. <i>200, 6 ; joint à</i> εὐεργεσίαι, PLAT. <i>Gorg. 509</i> c ; les connaissances <i>ou</i> arts utiles, XÉN. <i>Cyn. 12, 17 ;</i> αἱ κοιναὶ ὠφ. LYS. <i>257, 34,</i> les ressources communes, <i>càd</i>. les ressources de l’État, LYS. <i>157, 34 ;</i><br><b>      3</b> <i>en mauv. part,</i> butin : butin de chasse, XÉN. <i>Cyn. 6, 4, etc. ;</i> butin de guerre, POL. <i>1, 20, 1 ; 2, 3, 8, etc. ; joint à</i> λεία, PLUT. <i>M. 255</i> b ; <i>à</i> ἁρπαγή, PLUT. <i>Brut. 43, 46 ; différ. de</i> λάφυρον, butin général, ὠφέλεια <i>étant le butin particulier de chaque soldat,</i> POL. <i>3, 17, 7 ; au plur</i>. μεγάλας ὠφελείας ἁθροίζειν, PLUT. <i>Cleom. 12,</i> ramasser beaucoup de butin ; πολλῆς ὠφελείας κυριεύειν, DS. <i>15, 36,</i> se rendre maître d’un butin abondant ; αἱ ὠφέλειαι, le butin, POL. <i>3, 51, 11 ; 3, 86, 10, etc. ;</i> PLUT. <i>Flam. 5, etc. ; fig</i>. δι' ὠφελείας τίθεσθαι τὰ χρήματα, DH. <i>7, 37,</i> prendre l’argent pour butin ; <i>en parl. du produit d’un vol,</i> ANT. <i>115, 15</i>.<br><span><b><span class=\"arrow\"></span></b> ὠφέλεια, <i>forme att. usuelle ; ttef</i>. ὠφελία <i>forme d’anc. att. dans Thucydide, et en poésie dans les vers anapestiques,</i> EUR. <i>Andr. 539, etc. ;</i> AR. <i>Eccl. 576 ; ion</i>. ὠφελίη, HDT. <i>ll. cc. ;</i> ANTH. <i>6, 187, etc. ; Dans les inscr. att. seul</i>. ὠφελία CIA. <i>1, 85, 3 (5<sup>e</sup> siècle av. J.C.) ; v. Meisterh. p. 44, §§ 15, 32</i>.<br><span><b>Étym</b>. ὠφελέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωφελεια - ὠφέλεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G5623":"<h1>opheleo</h1>\n<p>Strong n° 5623 <i>Prononciation [o-fel-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>assister, être utile ou avantageux, profiter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠφελέω-ῶ</b> <span>(<i>impf</i>. ὠφέλουν, <i>f</i>. ὠφελήσω, <i>ao</i>. ὠφέλησα, <i>pf</i>. ὠφέληκα ; <i>pass. f</i>. ὠφεληθήσομαι, <i>ao</i>. ὠφελήθην, <i>pf</i>. ὠφέλημαι, <i>pl.q.pf</i>. ὠφελήμην)</span> secourir, assister, aider, <i>d’où</i> être utile, <i>abs</i>. ATT. ; <i>p. opp. à</i> βλάπτειν, THC. <i>6, 14 ;</i> XÉN. <i>Mem. 4, 8, 11 ;</i> PLAT. <i>Phæd. 107</i> d, <i>etc. ;</i> τινα, XÉN. <i>Cyr. 1, 4, 25, Mem. 1, 3, 1, etc. ; rar</i>. τινι, ESCHL. <i>Pr. 342, etc. ;</i> SOPH. <i>Ant. 560 ;</i> EUR. <i>Or. 663, etc. ;</i> AR. <i>Av. 420 ;</i> ARSTT. <i>Rhet. 1, 1,</i> à qqn ; XÉN. <i>Conv. 4, 24 ; Cyr. 2, 2, 27 ;</i> PLAT. <i>Ep. 315</i> c, <i>etc</i>. en qqe ch. ; οὐδέν <i>ou</i> μηδέν, PLAT. <i>Rsp. 526</i> b, <i>etc</i>. n’être utile en rien ; <i>avec double acc</i>. ὠφέλειαν ὠφ. τινα, PLAT. <i>Rsp. 519</i> e, <i>etc</i>. rendre service à qqn ; <i>avec un adj. ou un pron. neutre</i> ὠφ. τινά τι, SOPH. <i>Ant. 548,</i> être utile à qqn en qqe ch. ; μεγάλα τινά, PLAT. <i>Soph. 227</i> a ; πολλά τινα, XÉN. <i>Vect. 2, 1, etc</i>. rendre de grands services, beaucoup de services à qqn ; οὐδέν τινα, HDT. <i>3, 126 ;</i> ATT. (EUR. <i>Alc. 875, etc</i>.) n’être utile en rien à qqn ; ὠφ. τινα εἴς τι, THC. <i>4, 75 ;</i> πρός τι, ATT. être utile en vue de qqe ch. ; ἐπί τινι, EUR. <i>fr. 85,</i> en qqe ch. ; τινὰ ὠφ. <i>avec un part</i>. EUR. <i>Hipp. 970,</i> être utile à qqn en faisant qqe ch. ; <i>au part. prés. employé subst. :</i> οὐδεὶς ἔρωτος τοῦδ' ἐφαίνετ' ὠφελῶν, SOPH. <i>O.C. 436,</i> nul n’apparaissait pour m’aider à satisfaire ce désir<br><i>Pass. (f</i>. ὠφεληθήσομαι <i>ou</i> ὠφελήσομαι) être aidé, assisté, secouru : ὑπό τινος, ARSTT. <i>Nic. 8, 11 ;</i> πρός τινος, HDT. <i>2, 68 ;</i> παρά τινος, XÉN. <i>Mem. 1, 6, 14, etc. ;</i> PLAT. <i>Amat. 132</i> d, par qqn ; ἀπό τινος, PLAT. <i>Euthyphr. 15</i> a <i>ou</i> ἔκ τινος, THC. <i>8, 96 ;</i> XÉN. <i>Mem. 2, 4, 1,</i> tirer parti de qqn, XÉN. <i>Œc. 1, 15 ; 20, 29 ;</i> XÉN. <i>Mem. 2, 7, 8, etc. ; ou</i> de qqe ch., retirer un profit <i>ou</i> un avantage de qqe ch. THC. <i>3, 64 ;</i> XÉN. <i>Cyr. 5, 4, 34, etc. ;</i> PLAT. <i>Rsp. 346</i> d, <i>etc. ;</i> εἴς τι, THC. <i>4, 75 ;</i> XÉN. <i>Cyr. 2, 1, 26, etc. ;</i> PLAT. <i>Leg. 819</i> c, <i>etc. ; ou</i> πρός τι, XÉN. <i>Cyr. 2, 1, 25 ;</i> PLAT. <i>Theag. 127</i> d, <i>etc</i>. tirer parti (d’une chose) en vue d’une autre ; διά τι, PLAT. <i>Ep. 315</i> e, <i>360</i> b ; διά τινος, PLUT. <i>M. 38</i> e, retirer un profit au moyen de qqe ch. ; <i>avec un part</i>. ὠφελεῖσθαι ἰδόντα, THC. <i>2, 39,</i> profiter de ce qu’on a vu, <i>etc. ; avec un adj. ou un pron. neutre :</i> μεγάλα ὠφελεῖσθαι, PLUT. retirer de grands avantages ; πολλὰ ὠφελεῖσθαι, XÉN. <i>Cyn. 5, 27 ; 12, 1, etc. ;</i> πλείω ὠφ. THC. <i>8, 96 ;</i> XÉN. <i>Mem. 3, 11, 3, etc. ;</i> πλεῖστα, XÉN. <i>Cyr. 6, 1, 24,</i> retirer beaucoup, plus, un très grand nombre d’avantages ; οὐδὲν ὠφ. SOPH. <i>Ant. 550,</i> ne retirer aucun avantage ; <i>en mauv. part :</i> δι' ἁρπαγῆς ὠφελεῖσθαι, PLUT. <i>Marc. 19,</i> s’enrichir par le pillage.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg. ion</i>. ὠφέλεε, HDT. <i>3, 126. Pl.q.pf. 1 sg. att</i>. ὠφελήκη, PLAT. <i>Ap. 31</i> d. <i>Fut. moy. au sens pass</i>. ὠφελήσομαι, THC. <i>6, 18 ; 7, 67 ;</i> XÉN. <i>Mem. 1, 6, 14, etc. ;</i> PLAT. <i>Rsp. 343</i> b ; LYS. <i>157, 31, etc</i>.<br><span><b>Étym</b>. ὄφελος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωφελεω - ὠφελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G5624":"<h1>ophelimos</h1>\n<p>Strong n° 5624 <i>Prononciation [o-fel'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>profitable, utile</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὠφέλιμος, ος, ον</b> <span>[ῐ]</span><br><b>      1</b> secourable, XÉN. <i>Mem. 2, 7, 9 ;</i> PLAT. <i>Hipp. ma. 296</i> e, <i>etc. ;</i><br><b>      2</b> utile, avantageux, profitable, <i>en parl. de pers</i>. PLAT. <i>Men. 88</i> c, <i>96</i> e, <i>etc. ;</i> PLUT. <i>M. 86</i> f, <i>etc. ; d’ord. en parl. de choses,</i> THC. <i>1, 93 ;</i> XÉN. <i>An. 4, 1, 23 ;</i> PLAT. <i>Gorg. 499</i> c, <i>etc. ; p. opp. à</i> βλαϐερός, PLAT. <i>Rsp. 457</i> b, <i>etc. ; à</i> βλάπτων, XÉN. <i>Œc. 6, 4, etc. ; joint à</i> ἀγαθός, PLAT. <i>Prot. 333</i> e, <i>etc. ; à</i> χρήσιμος, XÉN. <i>Cyr. 6, 2, 34, etc. ;</i> ὠφ. τινι, THC. <i>1, 76 ;</i> XÉN. <i>Œc. 1, 7 ; Mem. 2, 7, 9 ;</i> PLAT. <i>Charm. 174</i> d, <i>Men. 98</i> c, <i>etc. ;</i> εἴς τινα THC. <i>1, 91,</i> utile à qqn ; εἴς τι, THC. <i>3, 68 ;</i> XÉN. <i>Œc. 5, 11, etc. ;</i> πρός τι, PLAT. <i>Rsp. 607</i> d ; ὑπέρ τινος, XÉN. <i>Cyr. 6, 2, 34,</i> utile pour qqe ch. ; <i>avec l’inf</i>. PLUT. <i>M. 87</i> d, utile pour, <i>etc</i>. ATT. ; τὸ ὠφέλιμον, PLAT. <i>Rsp. 457</i> d, <i>2 Alc. 145</i> c ; LUC. <i>Dom. 21, etc</i>. l’utile, l’avantage.<br><span>•<i> Cp</i>. -ώτερος, THC. <i>1, 91 ; 3, 37 ;</i> PLAT. <i>Rsp. 461</i> a ; <i>sup</i>. -ώτατος, PLAT. <i>Theæt. 179</i> a ; ARSTT. <i>Rhet. 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -η, PLAT. <i>Rsp. 607</i> d, <i>Men. 98</i> c, <i>Charm. 174</i> d.<br><span><b>Étym</b>. ὠφελέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ωφελιμος - ὠφέλιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>"};
